{{=<% %>=}}
<ch-step-list>
	<ch-step-list-item *ngFor="let stepItem of StepItems" class="{{Class}}" (click)="SelectedItem=stepItem.id; ItemClick();">
		{{stepItem.text}}
	</ch-step-list-item>
</ch-step-list>

tokens UnanimoWeb (color-scheme:dark|[light])
{   
    @color-scheme = light {
        //COLORS 
        #colors {
            surface-transp: #ffffff7f;
        }
        //OPACITY
        #opacity {
            mask-opacity: $opacity.s;
        }
    }
    @color-scheme = dark {
        //COLORS 
        #colors {
            surface-transp: #1212127f;
        }
        //OPACITY
         #opacity {
            mask-opacity: $opacity.l;
        }
    }
    //SPACING
    #spacing { 
        //TYPOGRAPHY -> Line height
        line-height-xs: 1.14em;
        line-height-s: 1.3em;
        line-height-m: 1.4em;
        line-height-l: 1.5em;
    }
}

styles UnanimoWeb
{   
    @import GeneXusUnanimo.Unanimo;
    @import GeneXusUnanimo.UnanimoControls;

    #region General 

        //hide submit button in iPhone/iPad
        input [title="submit"] [disabled] {
            -webkit-appearance: none;
        }
        html, body {
            background-color: $colors.alt-surface !important; 
            margin: 0px;
            font-family: $fonts.primary-regular,Helvetica,Arial,sans-serif;
            font-size: $fontSizes.s;
            line-height: 1.42857143; //bootstrap-based value
            height: 100%;
            scrollbar-width: thin;
            scrollbar-color: $colors.secondary-active $colors.gray01; 
        }
        .MainContainer {
            padding-inline-end: 15px;
            padding-inline-start: 15px;
            margin-inline-end: auto;
            margin-inline-start: auto;
        }
        .gx-ajax-error {
            width: calc(100% - 4px);
            background-color: $colors.error-light;
            border-inline-start: solid 4px;
            border-inline-start-color: $colors.error-dark;
            display: flex;
            justify-content: space-between;
            flex-direction: row-reverse;
            padding: 0px;
            margin: 0px;
        }
        .gx-ajax-error button {
            margin-inline-end: 16px;
            border: none;
            background-color: transparent;
            font-size: $fontSizes.l;
        }
        .gx-ajax-error button:hover {
            cursor: pointer;
        }
        .gx-ajax-error span {
            margin-inline-start: 16px;
        }
        div.gx-mask {
            position: absolute;
            background-color: black;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            animation: entermask 1s;
            -webkit-animation: entermask 1s;
            opacity: $opacity.mask-opacity;
        }
        body.gx-masked div.gx-mask {
            position: fixed;
            bottom: 0px;
        }

        body[dir="rtl"] div[data-align="right"] > div[data-align-outer]{
            width: inherit;
        }

        @media screen and (max-width: 767px) {
            .table-responsive {
                border:none;
            }
        }
    #endregion

    #region Buttons
        //Styling input buttons for iPad and iPhone
        input[type=button] {
            -webkit-appearance: none;
            -moz-appearance: none;
            appearance: none;
        }
        //BUTTON PRIMARY
        .Button.Primary {
            @include button-primary;
            gx-button-hovered-class: button-primary--hover;
            gx-button-focused-class: button-primary--focused;
            gx-button-highlighted-class: button-primary--active;
            gx-button-disabled-class: button-primary--disabled;
        }

        //BUTTON SECONDARY
        .Button.Secondary {
            @include button-secondary;
            gx-button-hovered-class: button-secondary--hover;
            gx-button-focused-class: button-secondary--focused;
            gx-button-highlighted-class: button-secondary--active;
            gx-button-disabled-class: button-secondary--disabled;
        }

        //BUTTON TERTIARY (OUTLINED)
        .Button.Tertiary {
            @include button-tertiary;
            gx-button-hovered-class: button-tertiary--hover;
            gx-button-focused-class: button-tertiary--focused;
            gx-button-highlighted-class: button-tertiary--active;
            gx-button-disabled-class: button-tertiary--disabled;
        }

        //BUTTON ROUNDED
        .Button.Rounded {
            @include button-rounded;
            gx-button-hovered-class: button-rounded--hover;
            gx-button-focused-class: button-rounded--focused;
            gx-button-highlighted-class: button-rounded--active;
            gx-button-disabled-class: button-rounded--disabled;
        }
    #endregion

    #region Textblock
        .text-helper-gray {
            color: $colors.gray03;
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.xs;
            letter-spacing: 0.2px;
        }
        .text-line-separator {
            display: flex;
            flex-direction: row;
            font-family: $fonts.primary-regular;
            color: $colors.on-background; 
        }
        .text-line-separator:before, .text-line-separator:after{
            content: "";
            flex: 1 1;
            border-bottom: 1px solid $colors.gray02;
            margin: auto;
        }
        .text-line-separator:before {
            margin-inline-end: 10px;
        }
        .text-line-separator:after {
            margin-inline-start: 10px;
        }
        .TextBlock, .Textblock {
            color: $colors.on-background;
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.s;
            gx-text-block-link-class: link-enabled;
            gx-text-block-visited-class: attribute-link--visited;
        }
        .TextblockExtraSmall {
            color: $colors.on-background;
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.xs;
        }
        .TextblockMedium {
            color: $colors.on-background;
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.m;
        }
        .TextblockLarge {
            color: $colors.on-background;
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.l;
        }
        @media screen and (max-width: 767px) {
            .heading-01 {
                font-size: $fontSizes.l;
            }
        }
    #endregion

    #region Title
        .Title {
            font-size: $fontSizes.xl;
            font-family: $fonts.primary-bold;
            display: inline-block;
            color: $colors.on-background;
        }
        .Subtitle {
            @include Title;
            letter-spacing: 0.40px;
            font-size: $fontSizes.l;
        }
        @media screen and (max-width: 767px) {
            .Subtitle {
                font-size: $fontSizes.l;
            }
        }
    #endregion

    #region Image
        .Image-20 {
            width: 20px;
        }
        .Image-25 {
            width: 25px;
        }
        .Icon-white-20{
            width:20px;
            filter: invert(98%) sepia(7%) saturate(4%) hue-rotate(33deg) brightness(105%) contrast(100%);
        }
        //Utility classes for changing svg color:
        .color-primary {
            filter: invert(40%) sepia(98%) saturate(2479%) hue-rotate(222deg) brightness(100%) contrast(90%);
        }
        @media screen and (max-width: 767px) {
            .Image {
                max-width: 100%;
            }
        }
    #endregion

    #region Action Group
        //responsive navbar
        .navbar {
            border: none; 
        }
        .navbar-toggle {
            width: 28px;
            height: 28px;
            position: relative;
            background-color: transparent;
            background-image: gx-image(GeneXusUnanimo.show_more);
            background-position: center;
            border: none;
            border-radius: $radius.s;
        }
        .navbar-toggle:hover {
            cursor: pointer;
            background-color: $colors.primary-hover-20;
        }
        .navbar-brand {
            padding-top: 7px;
            height: auto;
        }
        .navbar-nav {
            display: flex;
            gap: $spacing.inline-xl;
        }
        .navbar-nav > li { 
            margin: 0px;
        }
        .navbar-default .navbar-nav>li>a:hover {
            background-color: $colors.primary-hover-20;
        }
        .gx-action-group {
            display: flex;
            gap: $spacing.inline-xl;
        }
        .ww__actions-cell .ActionGroup .Button {
            display: block;
            font-size: $fontSizes.s;
            font-weight: normal;
            letter-spacing: 0.25px;
            text-align: start;
            width: 100%;
        }
        //Menu Action Group
        .MenuOption {
            color: $colors.surface;
            font-family: $fonts.primary-bold;
            font-size: $fontSizes.s;
            font-weight: bold;
            letter-spacing: 0.38px;
            line-height: 13px;
            text-align: center;
            text-transform: uppercase;
            text-decoration: none;
            padding: 8px 13px 8px 13px;
        }
        .gx-dropdown-menu .MenuOption {
            display: block;
            color: $colors.surface;
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.s;
            font-weight: normal;
            letter-spacing: 0.25px;
            line-height: 16px;
            text-transform: none;
            text-align: start;
        }
        a.MenuOption:hover {
            background-color: $colors.secondary-active !important;
        }
        .dropdown .MenuOption:hover {
            background-color: $colors.secondary;
        }
        .dropdown-toggle {
            @include MenuOption;
        }
        .dropdown-toggle:hover {
            background-color: $colors.secondary-active;
        }
        .dropdown-toggle .caret {
           display: inline-block;
           border-top: 4px dashed $colors.primary;
           border-inline-start: 4px solid transparent;
           border-inline-end: 4px solid transparent;
           margin-inline-start: 4px; 
           vertical-align: middle;
        }
        //horizontal divider
        .HorizontalLine {
            display: block;
            height: 1px;
            margin: 0px 8px;
            background-color: $colors.secondary-active;
        }
        .dropdown-menu {
            margin-top: 7px;
            background: $colors.secondary;
            border-radius: $radius.xl;
            box-shadow: 0px 3px 4px 0px rgba(0, 0, 0, 0.14),
            0px 3px 3px -2px rgba(0, 0, 0, 0.12),
            0px 1px 8px 0px rgba(0, 0, 0, 0.2);
            padding: 0px;
            padding-bottom: 3px;
        }
        .navbar-nav .dropdown {
            position: unset;
        }
        li.dropdown  {
            padding-top: 0px;
        }
        .dropdown-menu > li {
            margin: 0px;
        }
        //hide navbar-header if no caption
        .navbar-header span.navbar-brand:empty {
            display: none;
        }
        //center navbar items if there are placed on Header
        .HeaderContainer nav.ActionGroup {
            text-align: center;
        }
        .HeaderContainer .gx-navbar {
            padding-top: 6px;
        }
        li:empty { 
            display: none;
        }
        ul.nav {
            padding-inline-start: 0px;
        }

        div.ActionGroup:first-child {
            border-top-left-radius: 5px;
            border-bottom-left-radius: 5px;
        }
        .nav:before, .nav:after {
            content: none;
        }
        //using Unanimo buttons style
        .action-group .navbar-text { 
            color: $colors.primary;
            display: block;
        }
        .action-group .dropdown-toggle {
            @include action-group-option;
            color: $colors.primary;
            font-family: $fonts.primary-semibold;
            height: 28px;
            line-height: 10px;
        }
        .action-group .dropdown-menu {
            margin-top: 1px;
        }
        .action-group-option { 
            @include button-tertiary; 
            text-decoration: none;
            min-height: 28px;
            line-height: 26px;
            min-width: 80px;
            padding-inline-start: $spacing.inset-m;
            padding-inline-end: $spacing.inset-m;
            border-radius: $radius.s;
            text-align: center;
            white-space: nowrap;
        }
        .action-group-option a {
            text-decoration: none;
            color: $colors.primary;
        }
        .action-group-option-img {
            background-image: gx-image(GeneXusUnanimo.show_more);
        }
        .action-group .dropdown-toggle {
            border: solid 1px $colors.primary;
            border-radius: $radius.s;
        }
        .gx-dropdown-menu .action-group-option {
            display: block;
            color: $colors.on-background;
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.s;
            font-weight: normal;
            letter-spacing: 0.25px;
            text-transform: none;
            text-align: start;
            height: 28px;
            line-height: 28px;
            border: none;
        }
        .gx-dropdown-menu a.action-group-option:hover {
            background-color: $colors.primary-hover-20;
        }
        .gx-dropdown-menu .Button {
            display: block;
            color: $colors.on-background;
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.s;
            font-weight: normal;
            letter-spacing: 0.25px;
            text-transform: none;
            text-align: start;
            height: 28px;
            line-height: 28px;
            border: none;
            width: 100%;
        }
        .Submenu {
            background-color: $colors.surface;
            width: max-content;
        }
        .dropdown-toggle .TextBlock {
            color: $colors.primary;
        }
        ul.action-group-option {
            background: $colors.surface;
            padding: 0px;
            padding-bottom: 3px;
            border: none;
            border-radius: $radius.xl;
        }
        ul.action-group-option:hover {
            background: $colors.surface;
        }

        @media screen and (max-width: 767px) {
            .navbar-collapse[aria-expanded="true"]{ 
                display: flex;
                flex-direction: column;
            }
            .dropdown-menu {
                box-shadow: none;
            }
            .gx-action-group {
                margin-bottom: $spacing.stack-l;
            }
            .ww__actions-container .gx-action-group {
                margin-bottom: 0;
            }
            .navbar-nav {
                display: contents;
            } 
            .action-group .navbar-collapse .action-group-option {
                border: none;
            }
            .action-group .navbar-collapse .dropdown-toggle {
                border: none;
            }
            .action-group .navbar-collapse {
                padding-block: $spacing.stack-s;
                background: $colors.surface;
                border-radius: $radius.xl;
                box-shadow: $shadows.xs;
                position: absolute;
                z-index: 1;
            }
            .dropdown-toggle .caret {
                border-top: 4px solid transparent;
                border-bottom: 4px solid transparent;
                border-inline-start: 4px dashed $colors.primary;
                margin-inline-start: 6px;
                transform: rotate(90deg);
            }
            div[data-align="right"] .gx-navbar .navbar-collapse {
                inset-inline-end: 16px;
            }
            .ww__actions-container .navbar-collapse {
                padding-block: $spacing.stack-s;
                margin-bottom: $spacing.stack-m;
                background: $colors.surface;
                border-radius: $radius.xl;
                box-shadow: $shadows.xs;
                position: absolute;
                z-index: 1;
            }
            .ww__actions-container .navbar-collapse li input {
                background-color: $colors.surface;
                color: $colors.primary;
                border: none;
            }
            .ww__actions-container .navbar-collapse li input:hover {
                background-color: $colors.primary-hover-20;
            }
            .ww__actions-container .Submenu li input {
                color: $colors.on-background;
            }
            .ww__actions-cell .ActionGroup .navbar-header {
                display: block;
            }
            .dropdown .dropdown-menu {
                box-shadow: $shadows.s;
                position: fixed;
                inset-inline-start: 100px;
            } 
            div[data-align="right"] .dropdown .dropdown-menu {
                inset-inline-start: unset;
                inset-inline-end: 100px;
            }
            div[data-align="center"] .dropdown .dropdown-menu {
                inset-inline-start: unset;
                inset-inline-end: unset;
            }
            .navbar-collapse .dropdown-toggle {
                text-align: left;
                padding-inline: 16px;
            }
        }
        @media screen and (min-width: 768px) {
            .dropdown:hover>.dropdown-menu {
                //display: block;
            }
            .navbar-toggle {
                display: none;
            }
            .action-group .container-fluid {
                padding: 0px;
            }
        }

    #endregion

    #region Containers
        #region Group
            .Group {
                padding: 0px;
                border: 0px;
                margin: 0px;
                min-width: 0px;
            }
            .GroupTitle {
                color: $colors.on-background;
                font-family: $fonts.primary-bold;
                font-size: $fontSizes.m;
                letter-spacing: $spacing.letter-spacing-s;
                width: 100%;
                height: 30px;
                padding: 0;
                margin-bottom: $spacing.stack-l;
                border: 0;
                border-bottom: 1px solid $colors.gray01;
            }
            //Group content
            .Group > div {
                padding-inline-start: $spacing.inset-m;
            }
        #endregion

        #region Flex
            .Flex {
                column-gap: $spacing.inline-xl;
            }
            .actions-container {
                flex-wrap: wrap;
            }

            @media screen and (max-width: 767px) {
                .actions-container :nth-child(1){
                    //order: -1;
                    flex: 0 0 100%;
                }
            }
        #endregion
    #endregion

    #region GX Messages
        .gx-warning-message, .gx-error-message, .gx-success-message {
            font-size: $fontSizes.s;
            margin-block: $spacing.inline-l;
            display: block;
            padding-inline-start: 22px;
        }
        .ErrorMessages:before,
        .gx-warning-message:before,
        .gx-success-message:before {
            content: "";
            width: 20px;
            height: 20px;
            position: absolute;
            background-repeat: no-repeat;
            background-position: center center;
            background-size: 100%;
        }
        .ErrorMessages:before {
            inset-inline-start: $spacing.inline-m;
            background-image: gx-image(GeneXusUnanimo.error_ico);
        }
        .ErrorMessages, .gx-error-message, 
        .WarningMessages, .gx-warning-message,
        .gx-success-message {
            font-family: $fonts.primary-semibold;
            position: relative;
        }
        .ErrorMessages {
            color: $colors.error-dark;
            margin-inline-start: 28px;
        }
        .ErrorViewer {
            color: $colors.error-dark;
        }
        .gx-error-message {
            background-image: gx-image(GeneXusUnanimo.error_ico);
            background-repeat: no-repeat;
            background-position: left;
            padding-inline-start: 25px;
        }
        //Warning
        .WarningMessages {
            color: $colors.warning-dark;
            background-image: gx-image(GeneXusUnanimo.warning_ico);
            background-repeat: no-repeat;
            background-position-y: center;
            padding-inline-start: 28px;
        }
        .gx-warning-message:before {
            background-image: gx-image(GeneXusUnanimo.warning_ico);
            inset-inline-start: 0px;
        }
        .gx-warning-message {
            color: $colors.warning-dark;
        }
        //Error
        .gx-error-message:before {
            background-image: gx-image(GeneXusUnanimo.error_ico);
            inset-inline-start: -22px;
        }
        .gx-error-message {
            color: $colors.error-dark;
        }
        //Success
         .gx-success-message:before {
            background-image: gx-image(GeneXusUnanimo.success_ico_green);
            inset-inline-start: 0px;
        }
        .gx-success-message {
            color: $colors.success-dark;
        }
    #endregion

    #region Recent Links Container
        .RecentLinksMainTable {
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.s;
        }
        .RecentLinksContainer {
            background-color: $colors.surface;
            min-height: 40px;
            font-size: $fontSizes.s;
            display:flex;
            align-items: center;
            margin: 0 -15px;
            margin-bottom: $spacing.stack-xxl;    
        }
        .RecentLinksContainer > .row {
            width: 100%;
        }
        .RecentsTitle {
            gx-text-block-link-class: link-enabled;
        }
        .RecentLinkItem {
            color: $colors.gray03;
            gx-text-block-link-class: link-enabled;
            gx-text-block-highlighted-class: link-focus;
            margin-inline-end: $spacing.inline-xl;
        }
        .RecentLinkItem:focus {
            outline: none;
        }
        .RecentLinkItem:active {
            outline: none;
        }
        .RecentLinkItem:after {
            content: "/";
            position: relative;
            inset-inline-start: $spacing.inline-l;
        }
        .RecentLinksGrid > .row > div:last-child .RecentLinkItem:after{
            display: none;
        }
        .RecentLinksGrid > .row > div {
            padding-block: 0px;
            padding-inline: 0px;
            width: auto;
        }
        @media screen and (max-width: 767px) {
            .RecentLinksMainTable {
                overflow: hidden;
                max-height: 25px;
                padding: 5px;
                -moz-transition: max-height 0.5s ease-in-out;
                -webkit-transition: max-height 0.5s ease-in-out;
                -ms-transition: max-height 0.5s ease-in-out;
                transition: max-height 0.5s ease-in-out;
            }    
            .RecentLinksMainTableExpanded {
                max-height: 500px;
            }
            .RecentLinksGrid {
                padding-inline-start: 15px;
            }
        }
    #endregion

    #region Links
        .link-enabled {
            color: $colors.primary-enabled;
            text-decoration: underline;
            gx-text-block-hovered-class: link-hover;
            gx-attribute-hovered-class: link-hover;
            gx-text-block-focused-class: link-focus;
            gx-attribute-focused-class: link-focus;
        }
        .link-hover {
        color: $colors.primary-hover;
        }
        .link-focus {
            outline-width: $borders.small;
            outline-style: solid;
            outline-color: $colors.secondary-enabled;
            outline-offset: 3px;
        }
    #endregion

    #region Transaction Buttons
        //BTN SELECT
        .BtnSelect {
            @include button-secondary;
            height: 28px;
            line-height: $spacing.line-height-l;
            gx-button-hovered-class: button-secondary--hover;
            gx-button-highlighted-class: button-secondary--active;
            gx-attribute-focused-class: button-secondary--focused;
        }
        .ToolbarCellClass {
            margin-bottom: $spacing.stack-l;
            width: 100%;
            margin-inline-start: 0;
            text-align: center;
            display: flex;
            justify-content: center;
        }
        .BtnFirst,.BtnPrevious, .BtnNext, .BtnLast {
            @include button-secondary;
            background-position: center center;
            border: none;
            gx-button-hovered-class: navigationButtonsHover;
            gx-button-highlighted-class: navigationButtonsHighlighted;
            gx-button-focused-class: navigationButtonsFocus;
            padding-inline-start: $spacing.inline-xl;
            padding-inline-end: $spacing.inline-xl;
            height: 28px;
        }
        .navigationButtonsHighlighted {
            @include button-secondary--active;
            gx-button-focused-class: navigationButtonsHighlightedFocused;
        }
        .navigationButtonsHighlightedFocused {
            outline: none;
        }
        .navigationButtonsFocus {
            @include button-secondary--focused;
        }
        //BTN FIRST
        .BtnFirst {
            background-image: gx-image(GeneXusUnanimo.arrow_first);
            gx-button-highlighted-class: BtnFirst-highlighted;
        }
        .BtnFirst-highlighted {
            background-image: gx-image(GeneXusUnanimo.arrow_first);
        }
        //BTN PREVIOUS
        .BtnPrevious {
            background-image: gx-image(GeneXusUnanimo.arrow_left);
            gx-button-highlighted-class: BtnPrevious-highlighted;
        }
        .BtnPrevious-highlighted {
            background-image: gx-image(GeneXusUnanimo.arrow_left);
        }
        //BTN NEXT
        .BtnNext, .BtnNext:active {
            background-image: gx-image(GeneXusUnanimo.arrow_right);
        }
        //BTN LAST
        .BtnLast {
            background-image: gx-image(GeneXusUnanimo.arrow_last);
            gx-button-highlighted-class: BtnLast-highlighted;
        }
        .BtnLast-highlighted {
            background-image: gx-image(GeneXusUnanimo.arrow_last);
        }    
        .navigationButtonsHover {
            @include button-secondary--hover;
        }
        //BTN CONFIRM
        .GX_BtnEnter {
            @include button-secondary;
        }
        //BTN DELETE
        .BtnDelete {
            @include button-tertiary;
            height: 28px;
            min-width: 80px;
            border-radius: $radius.s;
            line-height: $spacing.line-height-l;
            gx-button-hovered-class: button-tertiary--hover;
            gx-button-highlighted-class: button-tertiary--active;
            gx-attribute-focused-class: button-tertiary--focused;
            gx-button-disabled-class: button-tertiary--disabled;
        }
        .button-secondary-active-focus {
            outline: none;
            color: $colors.primary-active;
        }
        //BTN CANCEL
        .BtnCancel {
            @include button-secondary;
            height: 28px;
            min-width: 80px;
            border-radius: $radius.s;
            line-height: $spacing.line-height-l;
            margin-inline-start: $spacing.inline-m;
            margin-inline-end: $spacing.inline-m;
            gx-button-hovered-class: BtnCancelHover;
            gx-button-highlighted-class: BtnCancelHighligted;
            gx-button-focused-class: BtnCancelFocus;
        }
        .BtnCancelHover {
            @include button-secondary--hover;
        }
        .BtnCancelHighligted {
            @include button-secondary--active;
            gx-button-focused-class: BtnCancelHighlightedFocus;
        }
        .BtnCancelHighlightedFocus {
            outline: none;
            color: $colors.primary-active;
        }
        .BtnCancelFocus {
            @include button-secondary--focused;
        }
        //BTN ENTER
        .BtnEnter {
            @include button-primary;
            height: 28px;
            min-width: 80px;
            border-radius: $radius.s;
            line-height: $spacing.line-height-l;
            gx-button-hovered-class: BtnEnterHover;
            gx-button-highlighted-class: BtnEnterHighlighted;
            gx-button-focused-class: BtnEnterFocus;
        }
        .BtnEnterHover {
            @include button-primary--hover;
        }
        .BtnEnterHighlighted {
            @include button-primary--active;
            gx-button-focused-class: BtnEnterHighlightedFocus;
        }
        .BtnEnterHighlightedFocus {
            outline: none;
            background-color: $colors.primary-active;
        }
        .BtnEnterFocus{
            @include button-primary--focused;
        }
        .btn-group {
            display: flex;
        }
    #endregion

    #region Transaction Prompts
        body:before{
            content: "";
            opacity: 0;
            transition: opacity .5s;
            z-index: 1;
        }
        .gx-popup-default {
            gx-popup-resize-handle-class: gx-popup-resize;
        }
        body.gx-popup-opened:before {
            content: "";
            position: absolute;
            width: 100%;
            height: 100%;
            background-color: black;
            opacity: $opacity.mask-opacity;
            z-index: 10;
            position: fixed;
        }
        .gx-popup-document {
            background-color: $colors.overlay-bg !important;
        }
        .gx-popup-document .title-container:first-child {
            display: none;
        }
        .gx-popup-document .form__table-level {
            border-top-color: $colors.surface;
        }
        .gx-popup-resize {
            content: gx-image(GeneXusUnanimo.resize_ico);
        }
        .gx-responsive-popup .gx-popup-resize {
            inset-inline-end: 6px;
            bottom: 6px; 
        }
        .gx-popup-document body, .PopupBorder {
            background-color: $colors.overlay-bg !important; 
        }
        .PopupBorder {
            background-color: $colors.overlay-bg; 
            border-radius: $radius.xl;
            box-shadow: $shadows.s;
            padding-top: $spacing.stack-l;
            padding-bottom: 11px;
        }
        //Popup title
        .PopupHeader {
            display: flex;
            justify-content: space-between;
        }
        .PopupHeader .PopupTitle {
            font-family: $fonts.primary-bold;
            color: $colors.on-background;
            font-size: $fontSizes.l;
            margin-inline-start: $spacing.inset-m;
            display: block;
            margin-top: $spacing.stack-l;
            margin-bottom: $spacing.stack-xl;
        }
        .PopupHeader .PopupHeaderButton:before {
            content: "";
            display: block;
            width: 24px;
            height: 24px;
            background-image: gx-image(GeneXusUnanimo.close_ico);
            cursor: pointer;
            position: relative;
            inset-inline-end: $spacing.inset-m;
        }
        .AdvancedContainerItemExpanded .WWFiltersCell {
            margin-top: $spacing.stack-s;
        }
        //Filter labels
        .WWFilterLabel:focus {

        }
        .WWFilterLabel,
        .WWDateFilterLabel {
            gx-text-block-link-class: WWFilterLabelLink;
        }
        .AdvancedContainerItem {
            border-bottom-width: $borders.extra-small;
            border-bottom-style: solid;
            border-bottom-color: $colors.gray01; 
            padding-block: 9px;
        } 
        .AdvancedContainerVisible .row:last-child .AdvancedContainerItem {
            border-bottom: 0;
        }
        //uncollapsed
        .AdvancedContainerItem .WWFilterLabel,
        .AdvancedContainerItem .WWDateFilterLabel {
            display: block;
            background-image: gx-image(GeneXusUnanimo.arrow_desc);
            background-position: top 3px right;
            background-repeat: no-repeat;
            background-size: 20px;
        }
        body[dir="rtl"] .AdvancedContainerItem .WWFilterLabel, .AdvancedContainerItem .WWDateFilterLabel  {
            background-position: top 3px left;
        }
        //collapsed
        .AdvancedContainerItemExpanded .WWFilterLabel,
        .AdvancedContainerItemExpanded .WWDateFilterLabel {
            background-image: gx-image(GeneXusUnanimo.arrow_asc);
        }
        .WWFilterLabel, .WWDateFilterLabel {
            display: block !important;
            position: relative;
        }
        .WWFilterLabelLink {
            font-size: $fontSizes.s;
            color: $colors.gray03;
            text-decoration: none;
            font-family: $fonts.primary-regular;
        }
        .AdvancedContainerItem {
            border-bottom-style:solid;
            border-bottom-width: $borders.extra-small;
            border-bottom-color: $colors.gray01;
            padding-block: 10px;
        }
        .TableRowHovered {
            background-color: $colors.row-hover;
        }
        .ReadonlyAttribute a {
            color: $colors.primary-enabled; 
            text-decoration: underline;
        }
        .ReadonlyAttribute a:hover {
            color: $colors.border-primary-hover;
        }
        .ReadonlyDownloadAttribute {
            width: 64px;
        }
        .DescriptionAttribute a{
            color: $colors.primary-enabled; 
            text-decoration: underline;
        }
        .DescriptionAttribute a:hover {
            color: $colors.border-primary-hover;
        }
        //PAGINATION BUTTONS
        .PagingButtonsFirst,
        .PagingButtonsPrevious,
        .PagingButtonsNext,
        .PagingButtonsLast
        {
            background-color: transparent;
            background-repeat: no-repeat;
            background-size: 23px;
            height: 32px;
            width: 32px;
            display: inline-block;
            padding: 0;
            background-position: center center;
            border: none;
            border-radius: 0;
            cursor: pointer;
            gx-button-hovered-class: button-secondary--hover;
            gx-button-disabled-class: PagingButtonsDisabled;
        }
        .PagingButtonsDisabled {
            opacity: .5 !important;
        }

        //Page Button First
        .PagingButtonsFirst {
            background-image: gx-image(GeneXusUnanimo.arrow_first);
            gx-button-highlighted-class: PagingButtonsFirst-highlighted;
            gx-button-focused-class: PagingButtonsFirst-focus;
        }
        .PagingButtonsFirst-highlighted {
            @include button-secondary--active;
            background-image: gx-image(GeneXusUnanimo.arrow_first);
        }
        .PagingButtonsFirst-focus {
            @include button-secondary--focused;
            gx-button-highlighted-class: button-secondary--focused;
        }
        //Page Button Previous
        .PagingButtonsPrevious {
            background-image: gx-image(GeneXusUnanimo.arrow_left);
            gx-button-highlighted-class: PagingButtonsPrevious-highlighted;
            gx-button-focused-class: PagingButtonsPrevious-focus;
        }
        .PagingButtonsPrevious-highlighted {
            @include button-secondary--active;
            background-image: gx-image(GeneXusUnanimo.arrow_left);
        }
        .PagingButtonsPrevious-focus {
            @include button-secondary--focused;
            gx-button-highlighted-class: button-secondary-focused-highlighted;
        }
        //Page Button Next
        .PagingButtonsNext {
            background-image: gx-image(GeneXusUnanimo.arrow_right);
            gx-button-highlighted-class: PagingButtonsNext-highlighted;
            gx-button-focused-class: PagingButtonsNext-focus;
        }
        .PagingButtonsNext-highlighted {
            @include button-secondary--active;
            background-image: gx-image(GeneXusUnanimo.arrow_right);
        }
        .PagingButtonsNext-focus {
            @include button-secondary--focused;
            gx-button-highlighted-class: button-secondary--focused;
        }
        //Page Button Last
        .PagingButtonsLast {
            background-image: gx-image(GeneXusUnanimo.arrow_last);
            gx-button-highlighted-class: PagingButtonsLast-highlighted;
            gx-button-focused-class: PagingButtonsLast-focus;
        }
        .PagingButtonsLast-highlighted {
            @include button-secondary--active;
            background-image: gx-image(GeneXusUnanimo.arrow_last);
        }
        .PagingButtonsLast-focus {
            @include button-secondary--focused;
            gx-button-highlighted-class: button-secondary--focused;
        }
        body[dir="rtl"] [class*='PagingButtons'] {
            transform: rotate(180deg);
        }
        //Paging footer
        .gx-grid-paging-bar {
            display: flex;
            justify-content: flex-end;
            padding-block: 5px;
        }
        //Btn cancel Prompt
        .PromptContainer .BtnCancel  {
            margin-inline-start: 0;
        }
        .PromptContainer .WWGridCell {
            margin-inline-start: 0px;
            width: 75%;
            height: 100vh;
            padding-inline-start: 15px; 
            padding-inline-end: 15px;
        }
        .PromptContainer .WWGridCell > .Table {
            height: 100vh;
            display: flex;
            flex-direction: column;
        }
        .PromptContainer .WWGridCell > .Table > .row:nth-child(2) {
            flex-grow: 1;
        }
        .PromptContainer .WWGridCell > .Table > .row:nth-child(3) {
            align-self: flex-end;
        }
        @media screen and (max-width: 767px) {
            .PromptContainer .WWGridCell {
                width: 100%;
            }
            .gx-responsive-popup.gx-popup {
                width: 90vw;
                top: 5vh;
                inset-inline-start: 5vw;
                height: fit-content;
            }
            .gx-responsive-popup .gx-popup-content {
                width: 100%;
            }

            .gx-responsive-popup .gx-popup-content > iframe {
                width: 90vw !important;
                height: fit-content;
            }
        }
    #endregion

    #region Form Container
        .TabsFormContainer {
            padding-inline-start: $spacing.inset-l;
            padding-inline-end: $spacing.inset-l;
        }
        .FiltersContainer {
            display: none;
            background: $colors.surface;
            padding: $spacing.inset-m;
            border: solid $borders.extra-small;
            box-shadow: $shadows.m;
        }
        .FiltersContainerVisible {
            display: inherit;
        }
        .TableTop {
            margin-bottom: $spacing.stack-l;
        }
        //expandible container
        .expandible-container {
            margin-inline-start: 257px;
            width: calc(100% - 274px);
            transition: margin-inline-start .3s, width .2s ease-out;
        }
        .expanded {
            margin-inline-start: 57px;
            width: calc(100% - 74px);
            transition: margin-inline-start .3s, width .2s ease-out;
        }
        .table-login {
            width: 360px;
            padding: 45px 50px 45px 50px;
            background: $colors.surface;
            border-radius: $radius.xl;
            box-shadow: $shadows.xxs;
        }

        @media screen and (max-width: 767px) {
            .TabsFormContainer {
                padding-inline-start: $spacing.inset-m;
                padding-inline-end: $spacing.inset-m ;
            }
            //hidden in xs
            .hidden-xs {
                display: none !important; 
            }
            .table-login {
                width: 100%;
            }
            .expandible-container {
                margin-inline-start: 0px;
                width: 100%; 
            }
        }

        @media (min-width: 768px) and (max-width: 991px) {
            .hidden-sm {
                display: none !important;
            }
        }
        @media (min-width: 992px) and (max-width: 1199px) {
            .hidden-md {
                display: none !important;
            }
        }
        @media (min-width: 1200px) {
            .hidden-lg {
                display: none !important;
            }
        }
    #endregion

    #region Attribute
        .Attribute {
            min-height: 28px;
            max-width: 100%;
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.s;
            padding-inline-start: $spacing.inset-s;
            padding-inline-end: $spacing.inset-s;
            border-color: $colors.gray04;
            color: $colors.on-background;
            background-color: $colors.attribute-bg;
            border-radius: $radius.l;
            gx-attribute-focused-class: AttributeFocusedClass;
            gx-readonly-class: ROAttribute;
            gx-label-class: attribute-label;
            gx-datepicker-image-class: datepicker-image;
            gx-prompt-image-class: gx-prompt;
        }
        // WW pattern compatible
        .ReadonlyAttribute {
            @include Attribute;
            padding-inline-start: 0px;
            padding-inline-end: 0px;
            color: $colors.on-background;
            background-color: transparent;
        }
        .ROAttributeSearch { 
            @include AttributeSearch;
            color: $colors.on-background;
        }
        //description attribute
        .attribute-description {
            gx-attribute-link-class: attribute-link;
            gx-attribute-visited-class: attribute-link--visited;
            gx-attribute-hovered-class: attribute-link--hover;
        }
        .attribute-link {
            color: $colors.primary-enabled; 
            text-decoration: underline;
        }
        .attribute-link--visited {
            @include attribute-link;
            color: $colors.primary-active; 
        }
        .attribute-link--hover {
            @include attribute-link;
            color: $colors.primary-hover; 
        }
        .form-control {
            display: block;
            border-width: 1px;
            border-style: solid;
        }
        .form-group {
            margin-bottom: 15px;
        }
        .form-horizontal .form-group:after {
            display: table;
            content: " ";
            clear: both;
        }
        .form-horizontal .form-group {
            margin-inline-start: -15px;
            margin-inline-end: -15px;
        }
        .input-group {
            position: relative;
            display: table;
        }
        .input-group .form-control {
            position: relative;
            z-index: 1;
            float: left;
        }
        input.Attribute:disabled ~ .input-group-btn {
            display: none;
        }
        body[dir="rtl"] .input-group .form-control {
            float: right;
        }
        .dp_container > .input-group {
            display: flex;
            align-items: center;
        }
        //error attribute
        .ErrorAttribute {
            @include Attribute;
            height: 28px;
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.s;
            color: $colors.on-background;
            border-radius: $radius.l;
            border-color: $colors.error-dark;
        }
        .Attribute.ErrorAttribute {
            border-color: $colors.error-dark;
            gx-attribute-focused-class: Attribute-ErrorAttribute-focused;
        }
        .Attribute-ErrorAttribute-focused {
            border-color: $colors.error-dark;
            box-shadow: 0px 0px 0px 1px #f02031;
        }
        .AttSubTitle {
            Label: attribute-label;
            width: auto !important;
            gx-attribute-focused-class: AttributeFocusedClass;
        }
        .AttSubTitle.Errorform-control {
            border-color: $colors.error-dark;
            gx-attribute-focused-class: AttSubTitle-Errorform-control-focused;
        }
        .AttSubTitle-Errorform-control-focused {
            border-color: $colors.error-dark;
            box-shadow: 0px 0px 0px 1px #f02031;
        }
        //warning attribute
        .WarningAttribute {
            @include Attribute;
            height: 28px;
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.s;
            color: $colors.on-background;
            border-radius: $radius.l;
            border-color: $colors.warning-dark;
        }
        .AttributeFocusedClass {
            border-color: $colors.secondary-enabled;
            box-shadow: 0px 0px 0px 1px #13142c;
        }
        //Image on Trn form
        .ImageAttributeLabel {
            @include attribute-label;
        }
        //Blobfile on Trn form
        .DownloadAttributeLabel {
            @include attribute-label;
        }
        .ReadonlyDownloadAttributeLabel {
            @include attribute-label;
        }
        //Audio on Trn form
        .AudioAttributeLabel {
            @include attribute-label;
        }
        //Video on Trn form
        .VideoAttributeLabel {
            @include attribute-label;
        }
        //show password on input = password
        .input-group input[data-gx-password-reveal] {
            width: auto; 
        }
        .gx-pwd-reveal-btn {
            position: absolute;
            z-index: 2;
            inset-inline-end: 0;
            top: 0;
        }
        .gx-pwd-reveal-btn .btn {
            border: none;
            background-color: transparent;
        }
        .gx-pwd-reveal-btn .btn:hover {
            background-color: transparent !important;
        }
        .gx-pwd-reveal-btn .glyphicon-eye-open {
            width: 28px;
            height: 28px;
            background-image: gx-image(GeneXusUnanimo.password_show);
            background-size: 20px; 
            background-repeat: no-repeat;
            background-position: center;
            cursor: pointer;
        }
        .gx-pwd-reveal-btn .glyphicon-eye-close {
            width: 28px;
            height: 28px;
            background-image: gx-image(GeneXusUnanimo.password_hidden);
            background-size: 20px; 
            background-repeat: no-repeat;
            background-position: center;
            cursor: pointer;
        }
        //tag attributes ("badges")
        .badge {
            gx-label-class: attribute-label; 
            border-radius: 20px;
            padding-inline-start: 20px;
            padding-inline-end: 7px;
            background-repeat: no-repeat;
            background-position: 5px 5px;
            background-size: 8px;
            border-style: solid;
            border-width: 1px;
            font-family: $fonts.primary-regular;
            font-size: 13px;
            color: black;
            white-space: nowrap;
        }
        body[dir="rtl"] [class*="badge-"] {
            background-position: center right 5px;
        }
        .badge-success {
            @include badge;
            background-color: $colors.success-light;        
            border-color: $colors.success-dark;  
            background-image: gx-image(GeneXusUnanimo.dot_green);
            background-position-y: center;
        }
        .Readonlybadge-success{
            @include badge-success;
        }
        .badge-warning {
            @include badge;
            background-color: $colors.warning-light;        
            border-color: $colors.warning-dark;
            background-image: gx-image(GeneXusUnanimo.dot_yellow);
            background-position-y: center;
        }
        .Readonlybadge-warning{
            @include badge-warning;
        }
        .badge-danger {
            @include badge;
            background-color: $colors.error-light;        
            border-color: $colors.error-dark;
            background-image: gx-image(GeneXusUnanimo.dot_red);   
            background-position-y: center;
        }
        .Readonlybadge-danger {
            @include badge-danger; 
        }
        .badge-info {
            @include badge;
            background-color: $colors.primary-hover-20;        
            border-color: $colors.primary;
            background-image: gx-image(GeneXusUnanimo.dot_purple);
            color: $colors.on-background;
            background-position-y: center;
        }
        .Readonlybadge-info {
            @include badge-info;
        }
        .badge-disabled {
            @include badge;
            background-color: $colors.gray02;        
            border-color: $colors.border-gray-03;
            background-image: gx-image(GeneXusUnanimo.dot_gray);
            color: $colors.on-background;
            background-position-y: center;
        }
        .Readonlybadge-disabled {
            @include badge-disabled;
        }
        //Image data type picker
        .ImageAttribute {
            gx-multimedia-upload-class: multimedia-upload;
            gx-multimedia-upload-change-class: multimedia-upload__change;
            gx-multimedia-upload-empty-class: multimedia-upload__clear;
            gx-readonly-class: ROImageAttribute;
        }
         //Audio data type picker
        .AudioAttribute {
            @include ImageAttribute;
        }
        //Video data type picker
        .VideoAttribute {
            @include ImageAttribute;
        }
        .multimedia-upload {
            border-color: $colors.gray04;
            border-style: solid;
            border-width: 1px;
            border-radius: $radius.l;
            position: relative;
            height: 85px;
            width: 150px;
            display: block;
            text-align: center;
            line-height:68px;
        }
        .multimedia-upload__change {
            background-image: gx-image(GeneXusUnanimo.edit_light);
            background-repeat: no-repeat;
            background-position: center;
            font-size: 0px;
            position: absolute;
            width: 28px;
            height: 28px;
            inset-inline-end: 30px;
            border-radius: $radius.s;
        }
        .gx-multimedia-upload .change-action {
            background-color: $colors.surface-transp;
        }
        .gx-multimedia-upload .change-action:hover {
            background-color: rgba(105, 110, 242, 0.2);
        }
        .multimedia-upload__clear {

        } 
        .gx-multimedia-upload .clear-action {
            @include multimedia-upload__change;
            background-image: gx-image(GeneXusUnanimo.delete_light);
            inset-inline-end: 0px;
        }
        .gx-multimedia-upload .clear-action {
            background-color: $colors.surface-transp;
        }
        .gx-multimedia-upload .clear-action:hover {
            background-color: rgba(105, 110, 242, 0.2);
        }
        .gx-multimedia-ro .form-control-static {
            min-height: unset;
            padding: 0;
        }
        //placeholder when multimedia has value
        DIV.gx-multimedia-upload A.gx-multimedia-download SPAN.gx-download-placeholder {
            background-image: gx-image(GeneXusUnanimo.projects);
            background-repeat: no-repeat;
            background-position: center;
            opacity: 1;
            height: 64px;
            display: block;
        }
        .ROImageAttribute {
            border-width: 0;
            width: 50px;
            max-width: 124px;
            max-height: 68px;
        }
        .ImageAttribute.gx-disabled {
            padding-block: 7px;
            border-width: 0;
            width: 40px;
            max-width: 124px;
            max-height: 68px;
        }
        img.Attribute {
            max-width: 64px;
            padding-block: 7px;
        }
        //Download Attribute (blobfile)
        .DownloadAttribute {
            gx-multimedia-upload-class: multimedia-upload;
            gx-multimedia-upload-change-class: multimedia-upload__change;
            gx-multimedia-upload-empty-class: multimedia-upload__clear;
        }
        img.DownloadAttribute {
            max-width: 64px;
            padding-block: 7px;
        }
        span.DownloadAttribute {
            display: inline-block;
            background-image: gx-image(GeneXusUnanimo.download_ico);
            background-repeat: no-repeat;
            background-position: center 7px; 
            border-width: 0;
            height: 32px;
            width: 32px;
        }
        A:not([href]) span.gx-download-placeholder {
            opacity: $opacity.m;
        }
        DIV.gx-multimedia-upload A.gx-multimedia-empty SPAN.gx-download-placeholder {
            background-image: gx-image(GeneXusUnanimo.video);
            opacity: 1;
        } 
        DIV.gx-multimedia-upload * {
            line-height:normal;
        }
        DIV.gx-multimedia-upload IMG {
            padding-top: 5px;
            vertical-align: middle;
            max-height: 78px;
            max-width: 140px;
        }
        DIV.gx-multimedia-upload DIV.fields-ct {
            background-color: $colors.overlay-bg; 
            border-bottom-right-radius: 8px;
            border-bottom-left-radius: 8px;
            padding-block: 20px;
            padding-inline: 30px;
            height: 100%;
            display: none;
            white-space: nowrap;
        }
        DIV.gx-multimedia-upload DIV.fields-ct .Button:first-child {
            display: block;
            margin-inline-start: auto;
            margin-inline-end: $spacing.inline-xl;
            margin-top: $spacing.stack-xl;
        }
        DIV.gx-multimedia-upload DIV.fields-ct .Button {
            display: block;
            margin-top: $spacing.stack-xl;
        }
        DIV.fields-ct .Button:hover { 
             cursor: pointer;
        }
        .fields-ct .row:first-child {
            display: flex;
            flex-direction: column;
        }
        .fields-ct .row:last-child div{
            display: flex;
        }
        //upload file modal dialog
        DIV.gx-multimedia-upload INPUT.field {
            @include Attribute;
            border-style: solid;
            border-width: 1px;
            float: none;
            margin-top: 23px;
            max-height: none;
            width: 400px;
            max-width: none;
            display: none;
        }
        DIV.gx-multimedia-upload INPUT.field-selected {
            display: inline;
        }
        label.option {
            @include attribute-label;
            display: block;
            padding-bottom: 4px;
        }
        label.option:hover {
            cursor: pointer; 
        }
        DIV.suggestions {
            position: absolute;
            font-size: $fontSizes.s;
            font-family: $fonts.primary-regular;
            color: $colors.surface-negative;
            background-color: $colors.surface;
            border-radius: $radius.xl;
            padding-block: 4px;
            box-shadow: $shadows.s;
        }
        DIV.suggestions DIV.current {
            background-color: $colors.primary-hover-20;
        }
        DIV.suggestions DIV {
            cursor: pointer;
            padding-inline-start: 4px;
            padding-inline-end: 4px;
            margin-inline-start: 4px;
            margin-inline-end: 4px;
        }
        //choose file button
        input[type="file"].field {
            border-style: none !important;
        }
        .field::-webkit-file-upload-button {
            @include button-tertiary;
            height: 28px;
            border-radius: $radius.s;
        }
        .field::-webkit-file-upload-button:hover {
            cursor: pointer;
        }
    #endregion

    #region Calendar
        .datepicker-image{
            content: gx-image(GeneXusUnanimo.calendar_ico);
        }

        .dp_container .Attribute + img {
            content: gx-image(GeneXusUnanimo.calendar_ico);

            border-radius : 0;
            padding : 2px;
            width : 28px;
            height : 28px;
            margin-inline-start : 3px;
            margin-top: 3px;
        }
        .input-group span.input-group-btn {
            float: left;
        }
        body[dir="rtl"] .input-group span.input-group-btn {
            float: right;
        }
        .input-group span.input-group-btn .btn{
            border-radius: 0;
            padding: 2px;
            width: 28px;
            height: 28px;
            display: flex;
            align-items: center;
            justify-content: center;
            margin-inline-start: 3px;
            gx-button-hovered-class: button-secondary--hover;
            gx-button-focused-class: button-secondary--focused;
        }
        .input-group span.input-group-btn .btn img{
            //width:20px;
        }
        .calendar {
            background-color: $colors.overlay-bg;
        }
        .calendar table {
            color: $colors.on-background;
            border-spacing: 1px;
            padding: 2px;
            border: 0;
            box-shadow: $shadows.xs;
        }
        .calendar thead .daynames {
            line-height: 0;
        }
        .calendar thead .name {
            text-transform: uppercase;
            color: $colors.primary-enabled;
            font-size: 0;
            font-family: $fonts.primary-semibold;
            min-width: 21px;
            padding-top: $spacing.stack-l;
        }
        .calendar thead .name::first-letter {
            font-size: $fontSizes.s;
        }
        .calendar thead .calendartitle {
            background-color: $colors.overlay-bg;
            text-transform: uppercase;
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.xs;
            color: $colors.on-background;
        }
        .calendar thead .calendarbutton.calendar-nav {
            font-size: $fontSizes.xl;
            font-family: $fonts.primary-light;
        }
        .calendar .calendarbutton {
            background: $colors.overlay-bg;
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.s;
        }
        .calendar thead tr:first-child td:first-child {
            font-size:$fontSizes.s;
        }
        .calendar .headrow .calendarbutton {
            line-height: 0.45em;
            font-size: $fontSizes.xs;
        }
        .calendar tbody .day {
            border-color: $colors.gray02;
            height: $spacing.stack-xl;
            width: $spacing.stack-xl;
            text-align: center;
            background: $colors.overlay-bg;
            font-size: $fontSizes.xs;
            font-family: $fonts.primary-regular;
        }
        .calendar tbody td.today {
            text-decoration: none;
        }
        .calendar tbody .day:hover {
            border-color: $colors.primary-enabled;
        }
        .calendar tbody td.selected {
            border-color: $colors.primary-enabled;
            color: $colors.on-background;
            background-color: rgba(105, 110, 242, 0.1);
            text-decoration: none;
        }
        //time
        .time .hour {
            background: transparent;
            border: 0px;
            font-family: $fonts.primary-regular;
            font-weight: lighter;
        }
        .time .colon {
            font-family: $fonts.primary-regular;
            font-weight: lighter;
        }
        .time .minute {
            background: transparent;
            border: 0px;
            font-family: $fonts.primary-regular;
            font-weight: lighter;
        }
        //Calendar Combo
        .calendar .calendarcombo .label {
            display: block;
            font-family: $fonts.primary-light;
            font-size: $fontSizes.xs;
            color: $colors.on-background;
            border-radius: 0;
        }
        .calendar .calendarcombo .label:hover {
            background-color: $colors.primary-enabled;
            color: $colors.on-primary;
        }
        .calendar .calendarcombo {
            top: 42px;
            width: 2.5em;
            transform: translateX(2px);
        }
    #endregion

    #region Grid 
        .Grid label.Attribute {
            padding: 0px;
            min-height: unset;
            background-color: transparent;
            border: none;
        }
        .ww__grid label.Attribute {
            padding: 0px;
            min-height: unset;
            background-color: transparent;
            border: none;
        }
        .Grid .gx_newrow {
            @include button-secondary;
            padding: 5px  $spacing.inset-m 5px $spacing.inset-m;
            border-radius: $radius.s;
            text-decoration: none;
        }
        .gx_newrow-focus-class {
            outline: none;
        }
        .Grid .gx_newrow:before {
            content: "+";
            margin-inline-end: $spacing.inline-m;
            font-size: 21px;
            position: relative;
            top: 2px;
        }
        .gx-grid-delete {
            width: 12px;
            margin-inline-end: $spacing.inset-xs;
        }
        .form-control-static {
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.s;
            margin: 0px;
            min-height: 34px;
            padding-block: 7px;
        }
        .GridHighlightedRow{
            background-color: $colors.form-container-bg;
            color: $colors.on-background;
            border-collapse: collapse;
            margin-top: 5px;
            margin-bottom: 10px;
            cursor: default;
            gx-grid-row-class: grid-row-highlight;
        }
        //Highlighted row
        .GridHighlightedRow .GridHighlightedRowTitle {
            font-family: $fonts.primary-bold;
            font-size: $fontSizes.s;
            color: $colors.on-background;
            border-bottom-width: $borders.extra-small;
            border-bottom-style: solid;
            border-bottom-color: $colors.gray01;
            padding-block: 7px;
            padding-inline-start: $spacing.inset-s;
            padding-inline-end: $spacing.inset-s;
        }
        .GridHighlightedRowTitle {
            cursor: pointer;
        }
        .GridHighlightedRow .form-control-static {  
            padding-block: 9px;
        }
        .GridHighlightedRow .gx-attribute {
            padding-inline-start: $spacing.inset-s;
            padding-inline-end: $spacing.inset-s;
        }
        //empty Grid text
        .GridNoDataText {
            color: rgb(18, 18, 18);
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.s;
            letter-spacing: 0.25px;
            line-height: 16px;
            background-color: $colors.surface;
            margin-top: 20px;
        }
        .gx-grid [data-gx-grid-nodata] {
            //margin-bottom: 0px;
        }
        //WW Trn Level Grid
        .WorkWith,.PromptGrid,.ViewGrid {
            text-align: start;
            table-layout: fixed;
            border-collapse: collapse;
        }
        .ViewGrid {
            width: 100%;
            margin-top: $spacing.inset-m;
        }
        .ViewGrid, .GridWithBorder {
            background-color: $colors.form-container-bg;
            border-collapse: collapse;
        }
        .ViewGridTitle, .Grid, .GridWithBorder {
            font-family: $fonts.primary-bold;
            font-size: $fontSizes.s;
            color: $colors.on-background;
        }
    #endregion

    #region Grid Row
        .grid-row-highlight {
            gx-table-row-hovered-class: TableRowHovered;
        } 
    #endregion

    #region Grid Column
        .gx-grid th > span {
            display: flex; 
            align-items: center;  
        }
        .gx-grid th[style*="text-align:end"] > span {
            justify-content: end;
        }
        .column-action {
            text-align: center !important;
            width: 50px;
            padding: 7px;
            border-bottom-width: 1px;
            border-bottom-color: $colors.gray01;
            border-bottom-style:solid;
        }
        .column-action .gx-image-link .attribute-action {
            padding-block: 8px;
            border-width: 0;
            width: 40px;
            max-width: 124px;
            max-height: 68px;
        }
        .WWTextActionColumn {
            width: 80px;
            border-bottom-width: 1px;
            border-bottom-color: $colors.gray01;
            border-bottom-style:solid;
        }
        //in grid Image
        .gx-grid > img {
            max-height: 48px;
        }
        //center images vertically when inside a grid column
        td.gx-tab-padding-fix-1.gx-attribute img {
            vertical-align: middle;
        }
        td.gx-attribute .form-control {
            display: inline-block;
            width: 100%;
            margin-top: 5px;
            margin-bottom: 5px;
        }
        td.gx-attribute .dp_container .Attribute {
            display: inline-block;
            border-width: 1px;
            margin-top: 5px;
            margin-bottom: 5px;
        }
        @media screen and (max-width: 767px) {
            .OptionalColumn {
                display: none;
            }
            .WWOptionalColumn {
                display: none;
            }
            td.gx-attribute .form-control {
                width: 100%;
            }
        }
    #endregion

    #region Prompt
        .gx-prompt {
            content: gx-image(GeneXusUnanimo.prompt_light); 
        }
        .SelectionAttribute {
            content: gx-image(GeneXusUnanimo.featured_green);
        }
        .PromptMainTable {
            background-color: $colors.overlay-bg;
        }
        .PromptAdvancedBarCell {
            border-inline-end-width: 1px;
            border-inline-end-style: solid;
            border-inline-end-color: $colors.gray01;
        }
        .PromptGrid {
            @include Grid;
            width: 100%;
        }
        .PromptGrid .gx-attribute {
            padding-inline-start: $spacing.inset-s;
            padding-inline-end: $spacing.inset-s;
        }
        .PromptGrid .PromptGridTitle {
            padding-inline-start: $spacing.inset-s;
            padding-inline-end: $spacing.inset-s;
        }
        .PromptGridTitle {
            position: relative;
        }
        .PromptGridTitle img{
            position: absolute;
            right:0;
        }
        //Prompt Grid Footer
        .PromptGridFooter {
            padding-top: $spacing.stack-m;
        }
        .GridHeaderRowPromptGrid {
            font-family: $fonts.primary-bold;
            font-size: $fontSizes.s;
            color: $colors.on-background;
            cursor: pointer;
        }
        .PromptGridGridRow {
            border-bottom-width: 1px;
            border-bottom-style: solid;
            border-bottom-color: $colors.gray01;
            border-width: 3px;
            border-inline-start-style: solid;
            border-inline-start-color: transparent;
            border-bottom: 0;
            gx-table-row-hovered-class: TableRowHovered;
        }
        .PromptGridOdd td {
            padding-block: 3px;
        }
        .BtnToggle {
            @include ww__button-filters--show;
            background-color: transparent;
        }
        .AdvancedContainer {
            visibility: hidden;
            padding-inline-end: 20px;
            position: absolute;
            z-index: 10;
            background-color: $colors.overlay-bg;
            width: 100%;
            min-height:  calc(100vh - 206px);
            transition: visibility 0s linear 0s, opacity 300ms;
        }
        .AdvancedContainerVisible {
            @include AdvancedContainer ;
            visibility: visible;
            display: inherit;
        }
        @media screen and (max-width: 767px) {
            .BtnToggle {
                margin-top: $spacing.stack-m;
                margin-bottom: $spacing.stack-m;
            }
            .AdvancedContainerVisible {
                top: 38px;
                width: fit-content;
            }
        }
    #endregion

    #region Table
        .Table {
            text-align: start;      
        }
        .Grid, .FreeStyleGrid, .GridWithBorder, .PromptGrid {
            background-color: $colors.form-container-bg;
            color: $colors.on-background;
            border-collapse: collapse;
            margin-top: $spacing.stack-s;
            margin-bottom: $spacing.stack-m;
            cursor: default;
        }
        .GridWithBorder {
            gx-grid-row-class: grid-row;
        }
        .GridTitle {
            font-family: $fonts.primary-bold;
            font-size: $fontSizes.s;
            color: $colors.on-background;
            cursor: pointer;
            border-bottom: $borders.extra-small solid $colors.gray01;
            padding-block: 7px;
            padding-inline: $spacing.inset-s;
        }
        .Grid {
            gx-grid-header-row-class: GridTitle;
            gx-grid-row-class: grid-row;
        }
        .Grid .form-control-static {  
            padding-block: 9px;
        }
        .GridWithBorder .GridWithBorderTitle {
            font-family: $fonts.primary-bold;
            font-size: $fontSizes.s;
            color: $colors.on-background;
            cursor: pointer;
            border-bottom: $borders.extra-small solid $colors.gray01;
            padding-block: 7px;
            padding-inline: $spacing.inset-s;
        }
        .GridWithBorder .form-control-static {  
            padding-block: 9px;
        }
        .GridWithBorder thead {
            border-top: $borders.extra-small solid $colors.gray01;
            border-inline-start: $borders.extra-small solid $colors.gray01;
            border-inline-end: $borders.extra-small solid $colors.gray01;
        }
        .GridWithBorder tbody {
            border-top: $borders.extra-small solid $colors.gray01;
            border-inline-start: $borders.extra-small solid $colors.gray01;
            border-inline-end: $borders.extra-small solid $colors.gray01;
        }
        .GridWithBorder tfoot {
            border-inline-start: $borders.extra-small solid $colors.gray01;
            border-inline-end: $borders.extra-small solid $colors.gray01;
            border-bottom: $borders.extra-small solid $colors.gray01;
        }
        .gx-freestyle-grid .form-control-static {
            padding-block: 10.5px;
        }
        .gx-freestyle-grid .form-control {
            margin-top: 6px;
            margin-bottom: 5px;
        }
        .Grid .gx-attribute {
            padding-inline: $spacing.inset-s;
        }
        .GridWithBorder .gx-attribute {
            padding-inline: $spacing.inset-s;
        }
        //freestyle grid row border
        .Grid > .row {
            border-bottom-width: $borders.extra-small;
            border-bottom-style: solid;
            border-bottom-color: $colors.gray01;
        }
        .GridWithBorder > .row {
            border-bottom-width: $borders.extra-small;
            border-bottom-style: solid;
            border-bottom-color: $colors.gray01;
        }
        .collapse-icon, .expand-icon {
            width: 17px;
            content: gx-image(GeneXusUnanimo.minus);
        }
        .expand-icon {
            content: gx-image(GeneXusUnanimo.plus);
        }
        @media screen and (max-width: 767px) {
            .gx-freestyle-grid .form-control-static {
                padding-block: $spacing.stack-s;
                min-height: 10px;
            }
            .gx-freestyle-grid .row {
                padding-block: $spacing.stack-s;
            }
        }
    #endregion

    #region Checkbox
        .gx-checkbox-wrapper > input {
            margin-inline-start: 0px;
        }
        //clear all default styles
        input[type="checkbox"] {
            -webkit-appearance: none;
            appearance: none;
            margin: 0px;
        }
        input[type="checkbox"]:hover {
            cursor: pointer;
        }
        input[type="checkbox"]:focus {
            outline: none;
        }
        input[type="checkbox"]:focus:after {
            border-width:2px;
        }
        input[type="checkbox"]:after {
            content: '';
            display: inline-block;
            vertical-align: text-top;
            width: 16px;
            height: 16px;
            background: transparent;
            border-color: $colors.gray04;
            border-style: solid;
            border-width: $borders.extra-small;
            border-radius: $radius.m;
            background-color: $colors.attribute-bg;
        }
        input[type="checkbox"]:disabled:after {
            background-color: $colors.on-disabled;
        }
        .gx-checkbox-wrapper input[checked]:after {
            border-color: $colors.border-primary-enabled;
        }
        .gx-checkbox-wrapper input[checked]:before {
            content: "";
            display: inline-block;
            width: 5px;
            height: 9.5px;
            border-style: solid;
            border-color: $colors.primary-enabled;
            border-top-width: 0;
            border-inline-end-width: 2px;
            border-bottom-width: 2px;
            border-inline-start-width: 0;
            transform: rotate(45deg);
            -webkit-transform: rotate(45deg);
            -ms-transform: rotate(45deg);
            border-radius: 0px;
            margin-top: 0px;
            margin-inline-end: 15px;
            margin-inline-start: 5px;
            margin-bottom: 5px;
            inset-inline-start: .5px;
            top: 2px;
            position: absolute;
        }
        .gx-checkbox-wrapper {
            background-color: transparent;
            border: none;
            padding: 0;
            padding-top: $spacing.stack-s;
        }
        //in Grid checkbox
        .gx-grid input[type="checkbox"][checked]::after {
            clip-path: polygon(21% 40%, 21% 40%, 8% 54%, 25% 68%, 36% 77%, 47% 65%, 48% 64%, 64% 47%, 75% 35%, 93% 13%, 81% 4%, 36% 54%);
            width: 12px;
            height: 12px;
            background-color: $colors.primary-enabled;
            position: relative;
            top: 2px;
            inset-inline-start: 1px;
        }
        .gx-grid input[type="checkbox"][checked] {
            border: solid $borders.extra-small $colors.primary-enabled;
            border-radius: $radius.m;
            width: 16px;
            height: 16px;
        }
        .gx-grid input[type="checkbox"]:disabled {
            background-color: $colors.on-disabled;
        }
        //checkbox title
        [data-gx-checkbox-title] {
            margin-inline-start: 22px;
        }
    #endregion

    #region Radio Button
        //clear all default styles
        input[type="radio"] {
            -webkit-appearance: none;
            appearance: none;
        }
        //custom style (overwriting browser's default)
        input[type="radio"] {
            margin-inline-end: 8px;
        }
        input[type="radio"]:focus {
            outline: none;
            box-shadow: 0px 0px 0px 3px black;
            width: 17px;
            height: 17px;
            border-radius: 10px;

        }
        input[type="radio"]:after {
            width: 15px;
            height: 15px;
            border-radius: 15px;
            position: relative;
            inset-inline-start: 1px;
            top: 1px;
            background-color: $colors.attribute-bg;
            content: '';
            display: inline-block;
            visibility: visible;
            border: 1px solid;
            border-color: $colors.gray04;
            cursor: pointer;
        }
        //checked
        input[type="radio"]:checked:after {
            background-color: $colors.primary;
            content: '';
            display: inline-block;
            visibility: visible;
            border: 3px solid;
            border-color: $colors.surface;
            cursor: pointer;
            box-shadow: 0px 0px 1px 2px;
            color: $colors.primary;
        }
        .gx-radio-button {
            display: block;
            margin-top: 7px;
            padding: 4px;
            padding-top: 5px;
        }
        .gx-radio-button-vertical {
            height: auto;
        }
        .gx-radio-label { 
            font-size: $fontSizes.s;
            padding-inline-end: $spacing.inline-l;
            gx-attribute-hovered-class: gx-radio-label--hover;
            gx-attribute-highlighted-class: gx-radio-label--active;
        }
        .gx-radio-label--hover {
            cursor: pointer;
        }
        .gx-radio-label--active {
            border-color: $colors.border-primary-active;
        }
        .gx-radio-label:hover:active {
            box-shadow: none;
            border-color: $colors.primary-active;
        }
        .gx-radio-label.active {
            box-shadow: none;
            background-color: $colors.primary;
            color: $colors.on-primary;
        }
        //disabled
        input[type="radio"]:disabled:after {
            background-color: $colors.on-disabled;
            color: $colors.gray04;
        }
    #endregion

    #region File Upload
        .FileUpload .fileinput-button {
            @include button-primary Button;
            padding-top: 3px;
            vertical-align: bottom;
            gx-button-hovered-class: button-primary--hover;
            gx-button-focused-class: button-primary--focused;
            gx-button-highlighted-class: button-primary--active;
            gx-button-disabled-class: button-primary--disabled;
        }
        .file-upload-hover {
            @include button-primary--hover;
        }
        .file-upload-highlighted {
            @include button-primary--active;
        }
        file-upload-focus {
            @include button-primary--focused;
        }
        .file-upload-highlighted {

        }
        .FileUpload .start {
            @include button-primary Button;
            gx-button-hovered-class: button-primary--hover;
            gx-button-focused-class: button-primary--focused;
            gx-button-highlighted-class: button-primary--active;
            gx-button-disabled-class: button-primary--disabled;
            cursor: pointer;
        }
        .FileUpload .start[disabled] {
            cursor: default;
        }
        .fileUploadDisabled {
            @include button-primary--disabled;
        }
        .FileUpload .cancel {
            @include button-secondary Button;
            gx-button-hovered-class: fileUploadCancelHover;
            gx-button-disabled-class: fileUploadDisabled;
            cursor: pointer;
        }
        .fileUploadCancelHover {
            @include button-secondary--hover;
        }
        .fileUploadDisabled {
            @include button-secondary--disabled;
        }
        .FileUpload .template-upload,
        .FileUpload .template-download {
            font-size: $fontSizes.s;
            font-family: $fonts.primary-regular;
            color: $colors.on-background;
        }
        //Progress bar
        .gx-fileupload .progress {
            height: $spacing.inset-xs;
            background-color: $colors.primary-disabled;
        }
        .progress-bar-success {
            background-color: $colors.primary;
        }
        //Progress extended
        .progress-extended {
            font-size: $fontSizes.s;
            font-family: $fonts.primary-regular;
            margin-top: $spacing.stack-s;
        }
        //Error text
        .text-danger {
            color: $colors.error-dark;
        }
        //Error label
        .label-danger {
            @include badge;
            background-color: $colors.error-light;        
            border-color: $colors.error-dark;
            background-image: gx-image(GeneXusUnanimo.dot_red); 
            margin-inline-end: $spacing.inline-l;
            color: black;
        }
        //Files table
        .gx-fileupload .table {
            width: 100%;
            max-width: 100%;
            background-color: $colors.surface;
            border-radius: $radius.xl;
            box-shadow: $shadows.xxs;
        }
        //Image preview
        .FileUpload .preview {
            padding-top: $spacing.inline-l;
        }
    #endregion

    #region Select
        select {
            padding-inline-start: 4px !important;
        }
        select.ErrorAttribute {
            appearance: none;
            padding-inline-end: 30px;
        }
        select.Attribute {
            height: auto;
        }
        //FF
        select.Attribute {
            scrollbar-color: $colors.secondary-active $colors.gray01;
            scrollbar-width: thin;
        }
        //Chrome, Edge
        select.Attribute::-webkit-scrollbar {
            width: 5px;
        }
        select.Attribute::-webkit-scrollbar-track {
            border-radius: 3px;
            background-color: $colors.gray01;
        } 
        select.Attribute::-webkit-scrollbar-thumb {
            border-radius: 3px;
            background-color: $colors.secondary-active;
        }
        select option {
            color: $colors.on-background;
            background-color: $colors.attribute-select-bg;
        }
    #endregion

    #region Progress Indicator
        //Overwrite bootstrap's default 
        .progress {
            height: 12px;
            background-color: $colors.gray02;
        }
        .progress-bar {
            background: $colors.primary;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: $fontSizes.xs;
            color: $colors.on-primary;
        }
        .progress-striped .progress-bar {
            background-image: none;
        }
        .progress-bar-title {
            display: inline-block;
            padding-bottom: 5px;
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.s;
            color: $colors.on-background;
        }
    #endregion

    #region Tab
        .nav-tabs>LI {
            display: inline-block;
        }
        .Tab {
            gx-tab-item-class: tab-item;
        }
        div.Tab UL.nav-tabs LI.active A {
            border-bottom: solid;
            border-bottom-width: 3px;
            border-bottom-color: $colors.primary-active;
            text-decoration: none;
        }
        div.Tab UL.nav-tabs LI A:hover {
            border-bottom: solid;
            border-bottom-color: $colors.secondary;
        }
        div.Tab UL.nav-tabs LI A:focus {
            outline: solid 1px;
            outline-color: $colors.primary-active;
        }
        //WorkWith tab
        div.ww__view__tab UL.nav-tabs LI A:hover {
            border-bottom: solid;
            border-bottom-color: $colors.secondary;
        }
        //WorkWith tab
        div.ww__view__tab UL.nav-tabs LI A:focus {
            outline: solid 1px;
            outline-color: $colors.primary-active;
        }
        div.ww__view__tab UL.nav-tabs LI.active A {
            border-bottom-color: $colors.primary-active;
            border-bottom-style: solid;
            text-decoration: none;
            color: $colors.on-background;
        }
        .tab-content {
            @include card;
            box-shadow: none;
            padding: $spacing.inset-m;
        }
    #endregion

    #region Scrollbar
        body::-webkit-scrollbar-track
        {
            border-radius: 10px;
            background-color: $colors.gray01;
        }
        body::-webkit-scrollbar
        {
            width: 10px;
            height: 10px;
            background-color: #F5F5F5;
        }
        body::-webkit-scrollbar-thumb
        {
            border-radius: 10px;
            background-color: $colors.secondary-active;
        }
    #endregion

    #region new classes
        //arrow icons
        .ico__arrow-first {
            background-image: gx-image(GeneXusUnanimo.arrow_first);
            background-position: center center;
        }
        .ico__arrow-prev {
            background-image: gx-image(GeneXusUnanimo.arrow_left);
            background-position: center center;
        }
        .ico__arrow-next {
            background-image: gx-image(GeneXusUnanimo.arrow_right);
            background-position: center center;
        }
        .ico__arrow-last {
            background-image: gx-image(GeneXusUnanimo.arrow_last);
            background-position: center center;
        }
        body[dir="rtl"] [class*="ico__arrow"] {
            transform: rotate(180deg);
        }
        .attribute-filter {
            gx-label-class: attribute-label;
            width: 100%;
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.s;
            padding-inline-start: $spacing.inset-s;
            padding-inline-end: $spacing.inset-s;
            gx-attribute-focused-class: AttributeFocusedClass;
            background-color: $colors.attribute-bg;
        }
        .attribute-search {
            @include attribute-filter;
            height: 28px;
            border-color: $colors.gray04; 
            color: $colors.on-background;
            border-radius: $radius.l;
            background-image: gx-image(GeneXusUnanimo.search);
            background-repeat: no-repeat;
            background-position: 1px;
            background-color: $colors.attribute-bg;
            padding-inline-start: 25px;
            gx-datepicker-image-class: datepicker-image;
        }
        body[dir="rtl"] .attribute-search {
            background-position: right;
        }
        textarea.attribute-search {
            padding-top: 4px;
        }
        select.attribute-search {
            background-image: none;
        }
        .TextActionAttribute { 
            gx-attribute-link-class: TextActionAttribute;
            background-color: transparent;
            font-size: $fontSizes.s;
            font-family: $fonts.primary-semibold;
            color: $colors.primary;
            text-transform: uppercase;
            border:none;
            border-radius: 0;
            padding-inline-start: $spacing.inset-s;
            padding-inline-end: $spacing.inset-s;
        }
        .TextActionAttribute>A {
            text-decoration: none;
        }
        .TextActionAttribute>A:hover {
            @include TextActionAttribute;
            background: $colors.primary-hover-20 !important;
            padding-block: 4px;
        }
        //to review
        .Errorattribute-search {
            @include attribute-search;
            height: 28px;
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.s;
            color: $colors.on-background;
            border-radius: $radius.l;
            border-color: $colors.error-dark;
        }
        //show error message in bottom position
        .ww-filter-cell div[style]{
            top: unset !important;
            inset-inline-start: unset !important;
        }
        .attribute-combo {
            @include attribute-filter;
            height: 28px;
            border-color: $colors.gray04;
            color: $colors.on-background;
            border-radius: $radius.l;
            margin-top: $spacing.inset-xs;
            margin-bottom: $spacing.inset-xs;
        }
        .ww__grid-container {
            @include card;
            padding: $spacing.inset-m;
            min-height: 423px;
        }
        .ww__grid {
            width: 100%;
            background-color: $colors.form-container-bg;
            margin-top: $spacing.inset-m;
            table-layout: fixed;
            border-collapse: collapse;
        }
        .ww__gridTitle span:hover{
            cursor: pointer;
        }
        .ww__grid-cell {
            padding: 0px;
            margin-bottom: $spacing.stack-xxl; 
        }
        .ww__grid-cell--expanded {
            width: 100%;
            margin-bottom: $spacing.stack-xxl; 
        }
        .expandible-container .ww__grid-cell--expanded {
            width: 100%;
            padding: 0px;
        }
        .expandible-container .ww__title-cell {
            margin-inline-start: 0%;
        }
        .ww__actions-container {
            margin-bottom: $spacing.stack-l;
            flex-wrap: wrap;
            row-gap: $spacing.stack-m;
        }
        .body-container .ww__actions-container {
            margin-bottom: $spacing.stack-xxl;
            flex-wrap: wrap;
            row-gap: $spacing.stack-m;
        }
        .ww__actions-cell ul{
            margin: 0px;
        }
        .ww__view__grid__actions-cell {
            margin-inline-start: auto;
        }
        .ww__button-filters--show {
            background-repeat: no-repeat;
            background-image: gx-image(GeneXusUnanimo.filter_light);
            background-position: center;
            border-width: 0;
            color: transparent;
            z-index: 2;
            background-color: transparent;
            width: 28px;
            height: 28px;
            padding: 0px;
            gx-button-hovered-class: button-secondary--hover;
        }
        .ww__button-filters--hide {
            @include ww__button-filters--show;
        }
        .ww__button-filters--applied {
            @include ww__button-filters--show;
            background-image: gx-image(GeneXusUnanimo.filter_applied);
        }
        .filters-container, .filters-container--visible {
            visibility: hidden;
            opacity: 0;
            padding-inline-start: 20px;
            padding-inline-end: 20px;
            position: absolute;
            inset-inline-end: -15px;
            background-color: $colors.form-container-bg;
            width: 100%;
        }

        .filters-container--visible {
            visibility: visible;
            opacity: 1;
            top: -33px;
            min-height: calc(100vh - 60px);
            padding-top: 10px;
            z-index: 1;
            transition: visibility 0s linear 0s, opacity 300ms;
        }
        .ww__view__grid-table .filters-container--visible {
            top: -16px;
            right: -16px;
            min-height: fit-content;
            border: solid 1px $colors.border-gray-02;
            padding-block-end: 32px;
        }
        //floating filters table (use it with a Section)
        .filters-container-floating--visible {
            @include filters-container--visible;
            width: auto;
            min-height: 200px;
            top: 0px;
            inset-inline-end: 15px;
            border: solid 1px $colors.gray01;
        }
        .filters-container__item {
            border-bottom-width: $borders.extra-small;
            border-bottom-style: solid;
            border-bottom-color: $colors.gray01; 
            padding-block: 9px;
            background-image: gx-image(GeneXusUnanimo.arrow_desc);
            background-position: top 10px right;
            background-repeat: no-repeat;
            background-size: 20px;
        }
        body[dir="rtl"] .filters-container__item {
            background-position: top 10px left;
        }
        .filters-container__item--expanded {
            background-image: gx-image(GeneXusUnanimo.arrow_asc);
        }
        .filters-container__item .input-group {
            display: none;
        }
        .filters-container__item--expanded .input-group {
            display: flex;
            align-items: center;
        }
        .filters-container__close {
            background-repeat: no-repeat;
            background-image: gx-image(GeneXusUnanimo.filter);
            border-width: 0;
            color: transparent;
            z-index: 2;
            width: 20px;
            height: 20px;
            padding: 0px;
            margin-bottom: 20px;
            background-color: $colors.form-container-bg;
            background-image: gx-image(GeneXusUnanimo.close_ico);
        }
        .filter-item__label {
            font-family: $fonts.primary-semibold;
            color: $colors.on-background;
            position: relative;
            gx-text-block-link-class: filter-item__link;
        }
        .filter-item__label strong {
            font-weight: normal;
            font-family: $fonts.primary-regular;
            padding-inline-start: 5px;
        }
        .filter-item__link {
            @include attribute-label;
            padding-top: 0px;
            text-decoration: none;
        }
        //view form
        .ww__view__tab {
            gx-tab-item-class: tab-item;
            gx-tab-page-hovered-class: tab-item--hover;
            gx-tab-page-selected-class: tab-item--selected;
            margin-bottom: $spacing.stack-xxl;
        }
        .ww__view__tab .tab-content {
            box-shadow: $shadows.xxs;
        }
        .ww__view__tab__form-container {
            padding-inline-start: $spacing.inset-m;
            padding-inline-end: $spacing.inset-m;
        }
        .ww__view__button-back {
            background-position: 0px center;
            background-repeat: no-repeat;
            padding-inline-start: 28px;
            background-image: gx-image(GeneXusUnanimo.arrow_left_light);
            font-family: $fonts.primary-semibold;
            font-size: 14px;
            letter-spacing: 0.25px;
            text-align: start;
            text-transform: uppercase;
            gx-attribute-link-class: ww__view__button-back__link;
        }
        body[dir="rtl"] .ww__view__button-back {
            background-position: right; 
            background-image: gx-image(GeneXusUnanimo.arrow_right_light);
        }
        .ww__view__button-back__link {
            color: $colors.primary-enabled;
            text-decoration: none;
        }
        .ww__view__button-back>A:hover {
            color: $colors.primary-hover;
        }
        .ww__view__title-table { 
            gap: 20px;
            align-items: center;
        }
        //styling view grid
        .ww__view__grid-table .ww__grid-cell {
            width: 83.33333%;
            margin: 0;
        }
        .ww__view__grid-table .ww__grid-cell:only-child {
            width: 100%;
        } 
        .ww__view__grid-table .ww__grid-container {
            box-shadow: none;
            padding: 0;
        }
        .form__cell, .form__cell-advanced {
            padding-block: 12px;
            padding-inline-start: 15px;
            border-collapse: collapse;
            border-color: $colors.gray01;
            border-bottom-style: solid; 
            border-bottom-width: 1px;
        }

        //Transaction's Form
        .form-container {
            @include card;
            padding: $spacing.inset-m;    
            margin-bottom: 120px; 
        }
        .form__cell .form-group {
            margin-bottom: 0px;
        }
        .form__cell-advanced .form-group {
            margin-bottom: 0px;
        }
        .title-container {
            margin-bottom: $spacing.stack-l;
        }
        .form__actions--fixed {
            height: 90px;
            position: fixed;
            bottom: 0;
            inset-inline-end: 0;
            z-index: 1;
            box-shadow: 0px -1px 10px 0px rgba(0, 0, 0, 0.30);
            background-color: $colors.footer-actions-bg;
        }
        .form__actions--fixed .gx-action-group {
            padding-inline-end: $spacing.inset-m;
            flex-direction: row-reverse;
        }
        .form__table-level {
            border-top-style: solid;
            border-top-width: 32px;
            border-top-color: $colors.alt-surface;
            width: calc(100% + 52px);
            margin-inline-start: -26px; 
            padding-inline: 19px;
            padding-top: 10px;
        }
        .form__table-level:after {
            content: "";
            display:block;
            height: 1px;
            position:absolute;
            border-top-width: 10px;
            border-top-style: solid;
            border-top-color: $colors.form-container-bg;
            width: calc(100% + 2px);
            inset-inline-start: -1px;
            top: 0;
            border-bottom-left-radius: $radius.xl;
            border-bottom-right-radius: $radius.xl;
            box-shadow: $shadows.xxs;
        }
        .form__table-level:before {
            content: "";
            display:block;
            height: 1px;
            position:absolute;
            border-top-width: 10px;
            border-top-style: solid;
            border-top-color: $colors.form-container-bg;
            width: calc(100% + 2px);
            inset-inline-start: -1px;
            top: 23px;
            border-top-left-radius: $radius.xl;
            border-top-right-radius: $radius.xl; 
        }
        .form__table-level > .row:first-child > .form__cell {
            border: none;
        }
        .form__table-level .Grid {
            width: 100%;
        }

        .form__table-level .heading-04 {
            position: relative;
            top: -8px;
            inset-inline-start: $spacing.inset-s;
        }

        .form__toolbar-cell {
            width: 100%;
            margin-inline-start: 0;
            text-align: center;
            display: flex;
            justify-content: center;
        }

        //error message in Grid column
        .gx-error__message-container {
            height: 24px;
            line-height: 24px;
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.xs;
            background-color: $colors.overlay-bg;
            border-radius: $radius.xl;
            box-shadow: $shadows.l;
            padding-inline-end: $spacing.inset-s;
        }

        @media screen and (max-width: 767px) {
            .form__actions--fixed {
                padding-inline-end: 15px;
            }
            .form__actions--fixed .gx-action-group {
                padding-inline-end: $spacing.inset-xs;
            }
            .filters-container {
                position: unset;
            }
            .filters-container--visible {
                position: fixed;
                top: 150px;
                width: calc(100% - 32px);
                inset-inline-end: 16px;
            }
            .body-container .ww__actions-container {
                margin-bottom: $spacing.stack-l;
            }
        }
    #endregion  
}

tokens Unanimo (color-scheme:[light]|dark)
{

    //BORDER WIDTH
    #borders  {
        extra-small: 1px;
        small: 2px;
    }

    //BORDER RADIUS
    #radius  {
        xs: 1px;
        s: 2px;
        m: 3px;
        l: 4px;
        xl: 6px;
    }

    //COLORS 
    @color-scheme = light {
        #colors
        {
            #region Unanimo_Colors
                primary: #696ef2;
                secondary: #13142c;
            #endregion

            #region Background_Colors
                surface: #ffffff;
                alt-surface: #f3f4f6;
                surface-negative: #121212;
                elevation-01: $colors.surface;
                elevation-02: $colors.surface;
                elevation-03: $colors.surface;
                elevation-04: $colors.surface;
                sidebar-bg: $colors.secondary;
                item-hover: $colors.secondary-hover; 
                item-active: $colors.secondary-active;
                row-hover: $colors.gray01;
                row-active: rgba(105, 110, 242, 0.2);
                header-bg: $colors.secondary;
                header-separator-bg: $colors.primary;
                form-container-bg: $colors.surface;
                footer-actions-bg: $colors.alt-surface;
                attribute-bg: $colors.surface;
                attribute-select-bg: $colors.surface;
                overlay-bg: $colors.surface;
            #endregion

            #region States_Primary
                primary-enabled: $colors.primary; 
                primary-active: #3015b0;
                primary-hover: #413cd4;
                primary-hover-20: #d9daf3;
                primary-disabled: $colors.gray03;
            #endregion

            #region States_Secondary
                secondary-enabled: $colors.secondary;
                secondary-active: #2a2c5f;
                secondary-hover: #202143;
                secondary-disabled: $colors.gray03;
            #endregion

            #region Grays
                gray01: #e0e0e0; 
                gray02: #c3c4c8;
                gray03: #939498; 
                gray04: #575965;
            #endregion    

            #region Alerts
                error-dark: #f02031;
                error-light: #ffeaee;
                warning-dark: #ff8000;
                warning-light: #ffe7e6;
                success-dark: #02a08b;
                success-light: #e1f3f1;
            #endregion

            #region Auxiliary
                destructive: #f44336;
                zebra-grid: #fafafa;
            #endregion

            #region On_Colors
                on-primary: $colors.surface;
                on-secondary: $colors.surface;
                on-background: #000000;
                on-alert: $colors.surface-negative;
                on-disabled: $colors.gray02;
            #endregion

            #region Borders_Primary
                border-primary-enabled: $colors.primary;
                border-primary-active: $colors.primary-active; 
                border-primary-hover: $colors.primary-hover; 
                border-primary-disabled: $colors.gray03;
            #endregion

            #region Borders_Secondary
                border-secondary-enabled: $colors.secondary;
                border-secondary-active: $colors.secondary-active;
                border-secondary-hover: $colors.secondary-hover; 
                border-secondary-disabled: $colors.gray03;
            #endregion

            #region Borders_Tertiary
                border-tertiary-enabled: $colors.tertiary;
                border-tertiary-active: $colors.tertiary-active;
                border-tertiary-hover: $colors.tertiary-hover; 
                border-tertiary-disabled: $colors.gray03;
            #endregion

            #region Borders_Gray
                border-gray-01: $colors.gray01;
                border-gray-02: $colors.gray02;
                border-gray-03: $colors.gray03;
                border-gray-04: $colors.gray04;
            #endregion

            #region Borders_Error
                border-error: $colors.error-dark;
                border-warning: $colors.warning-dark;
                border-success: $colors.success-dark;
            #endregion
        }
    }

    @color-scheme = dark {
        #colors
        {
            #region Unanimo_Colors
                primary: #a9acf8;
                secondary: #34334e;
            #endregion

            #region Background_Colors
                surface: #121212;
                alt-surface: #1c1c1e;
                surface-negative: #ffffff;
                elevation-01: #242426;
                elevation-02: #2c2c2e;
                elevation-03: #353537;
                elevation-04: #3e3e40;
                sidebar-bg: $colors.elevation-01;
                item-hover: $colors.elevation-04; 
                item-active: $colors.gray01;
                row-hover: $colors.elevation-04;
                row-active: $colors.gray01;
                header-bg: $colors.elevation-01;
                header-separator-bg: $colors.gray01;
                form-container-bg: $colors.elevation-01;
                footer-actions-bg: $colors.elevation-01;
                attribute-bg: transparent;
                attribute-select-bg: $colors.alt-surface;
                overlay-bg: $colors.elevation-02;
            #endregion

            #region States_Primary
                primary-enabled: $colors.primary;
                primary-active: #858af6;
                primary-hover: #ccccfb;
                primary-hover-20: #5a5edc33;
                primary-disabled: $colors.gray03;
            #endregion

            #region States_Secondary
                secondary-enabled: $colors.secondary;
                secondary-active: #666483;
                secondary-hover: #53516e;
                secondary-disabled: $colors.gray03;
            #endregion

            #region Grays
                gray01: #575965;
                gray02: #939498;
                gray03: #c3c4c8; 
                gray04: #e0e0e0;
            #endregion

            #region Alerts
                error-dark: #f9464e;
                error-light: #ffeaee;
                warning-dark: #ffab13;
                warning-light: #ffe7e6;
                success-dark: #50beae;
                success-light: #e1f3f1;
            #endregion

            #region Auxiliary
                destructive: #ef5350;
                zebra-grid: #323234;
            #endregion

            #region On_Colors
                on-primary: $colors.surface;
                on-secondary: #e9e9e9;
                on-background: $colors.on-secondary;
                on-alert: $colors.surface-negative;
                on-disabled: $colors.gray02;
            #endregion

            #region Borders_Primary
                border-primary-enabled: $colors.primary;
                border-primary-active: $colors.primary-active; 
                border-primary-hover: $colors.primary-hover; 
                border-primary-disabled: $colors.gray03;
            #endregion

            #region Borders_Secondary
                border-secondary-enabled: $colors.secondary; 
                border-secondary-active: $colors.secondary-active;
                border-secondary-hover: $colors.secondary-hover; 
                border-secondary-disabled: $colors.gray03;
            #endregion

            #region Borders_Gray
                border-gray-01: $colors.gray04;
                border-gray-02: $colors.gray03;
                border-gray-03: $colors.gray02;
                border-gray-04: $colors.gray01;
            #endregion

            #region Borders_Error
                border-error: $colors.error-dark;
                border-warning: $colors.warning-dark;
                border-success: $colors.success-dark;
            #endregion
        }
    }

    //ELEVATION
    #shadows { 
        xxxs: 0px 1px 1px 0px rgba(0, 0, 0, 0.14);
        xxs: 0px 2px 2px 0px rgba(0, 0, 0, 0.14);
        xs: 0px 3px 4px 0px rgba(0, 0, 0, 0.14); 
        s: 0px 4px 5px 0px rgba(0, 0, 0, 0.14);
        m: 0px 6px 10px 0px rgba(0, 0, 0, 0.14);
        l: 0px 8px 10px 1px rgba(0, 0, 0, 0.14);
        xl: 0px 9px 12px 1px rgba(0, 0, 0, 0.14);
        xxl: 0px 12px 17px 2px rgba(0, 0, 0, 0.14);
    }

    //OPACITY
    #opacity
    {
        s: 0.1;
        m: 0.25;
        l: 0.5;
    }

    //SPACING
    #spacing { 
        //LAYOUT -> Inset
        inset-xs: 4px;
        inset-s: 8px;
        inset-m: 16px;
        inset-l: 32px;

        //LAYOUT -> Stack
        stack-xs: 2px;
        stack-s: 4px;
        stack-m: 8px;
        stack-l: 16px;
        stack-xl: 24px;
        stack-xxl: 32px;
        stack-xxxl: 64px;
        stack-xxxxl: 128px;

        //LAYOUT -> Inline
        inline-xs: 2px;
        inline-m: 4px;
        inline-l: 8px;
        inline-xl: 16px;
        inline-xxl: 24px;
        inline-xxxl: 32px;

        //TYPOGRAPHY -> Letter spacing
        letter-spacing-xs: 0.2px;
        letter-spacing-s: 0.4px;
        letter-spacing-m: 0.8px; 
        letter-spacing-l: 1.6px;
        letter-spacing-xl: 3.2px;
    }

    //TYPOGRAPHY -> Font 
    #fonts  {
        primary-light: SourceSansPro-Light;
        primary-regular: SourceSansPro-Regular;
        primary-semibold: SourceSansPro-SemiBold;
        primary-bold: SourceSansPro-Bold;
    }    

    //TYPOGRAPHY -> Font Sizes
    #fontSizes  {
        xs: 11px; 
        s: 14px;  
        m: 18px;
        l: 22px;
        xl: 28px;
    }
}

styles Unanimo
{   
    #region Fonts  
        @font-face { 
        font-family: SourceSansPro-Light;
        src: gx-file(GeneXusUnanimo.Unanimo_SourceSansPro-Light_ttf);
        }
        @font-face {
        font-family: SourceSansPro-Regular;
        src: gx-file(GeneXusUnanimo.Unanimo_SourceSansPro-Regular_ttf);
        }
        @font-face {
        font-family: SourceSansPro-SemiBold;
        src: gx-file(GeneXusUnanimo.Unanimo_SourceSansPro-SemiBold_ttf);
        }
        @font-face {
        font-family: SourceSansPro-Bold;
        src: gx-file(GeneXusUnanimo.Unanimo_SourceSansPro-Bold_ttf);
        }
    #endregion

    #region Attribute
        .Attribute {
            height: 28px;
            max-width: 100%;
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.s;
            padding-inline-start: $spacing.inset-s;
            padding-inline-end: $spacing.inset-s;
            border-width: 1px;
            border-style: solid;
            border-color: $colors.gray04;
            color: $colors.on-background;
            background-color: $colors.attribute-bg;
            border-radius: $radius.l;
            gx-attribute-focused-class: AttributeFocusedClass;
            gx-readonly-class: ROAttribute;
            gx-label-class: attribute-label;
            //gx-datepicker-image-class: datepicker-image;
            //gx-prompt-image-class: gx-prompt;
        }
        .ROAttribute {
            @include Attribute;
            padding-inline-start: 0px;
            padding-inline-end: 0px;
            color: $colors.on-background;
            background-color: transparent;
            overflow-wrap: anywhere;
            border-style: none;
        }
        .AttributeFocusedClass {
            border-color: $colors.secondary-enabled;
            box-shadow: 0px 0px 0px 1px #13142c;
        }
        .AttributeSearch {
            @include Attribute;
            padding-inline-start: 25px;
            border-color: $colors.gray04;
            color: $colors.on-background;
            border-radius: $radius.l;
            background-image: gx-image(GeneXusUnanimo.search);
            background-repeat: no-repeat;
            background-position: 1px;
        }
    #endregion

    #region Buttons
        .Button {
            white-space: normal;
            height: 28px;
            padding-inline-start: $spacing.inset-m;
            padding-inline-end: $spacing.inset-m;
            border-radius: $radius.s;
            min-width: 80px;

            //button primary defaults
            background-color: $colors.primary;
            font-size: $fontSizes.s;
            font-family: $fonts.primary-semibold;
            color: $colors.on-primary;
            text-transform: uppercase;
            border:none;
        }
        //BUTTON PRIMARY
        .button-primary {
            background-color: $colors.primary;
            font-size: $fontSizes.s;
            font-family: $fonts.primary-semibold;
            color: $colors.on-primary;
            text-transform: uppercase;
            border:none;
            gx-button-hovered-class: button-primary--hover;
            gx-button-focused-class: button-primary--focused;
            gx-button-highlighted-class: button-primary--active;
            gx-button-disabled-class: button-primary--disabled;
        }
        .button-primary--hover {
            background-color: $colors.primary-hover;
        }
        .button-primary--active {
            background-color: $colors.primary-active;
            box-shadow: none;
            outline: none;
        }
        .button-primary--focused {
            background-color: $colors.primary;
            outline-width: $borders.small;
            outline-style: solid;
            outline-color: $colors.secondary-enabled;
            outline-offset: -2px;
        }
        .button-primary--disabled {
            background-color: $colors.gray03;
            color: $colors.on-disabled;
            cursor: auto;
        }
        //BUTTON SECONDARY
        .button-secondary {
            background-color: transparent;
            font-size: $fontSizes.s;
            font-family: $fonts.primary-semibold;
            color: $colors.primary;
            text-transform: uppercase;
            border:none;
            gx-button-hovered-class: button-secondary--hover;
            gx-button-focused-class: button-secondary--focused;
            gx-button-highlighted-class: button-secondary--active;
            gx-button-disabled-class: button-secondary--disabled;
        }
        .button-secondary--hover {
            background-color: $colors.primary-hover-20;
        }
        .button-secondary--focused {
            border:none;
            background-color: transparent;
            outline-width: $borders.small;
            outline-style: solid;
            outline-color: $colors.secondary-enabled;
            outline-offset: -2px;
            color: $colors.primary;
        }
        .button-secondary-focused-highlighted {
            outline: none;
            background-color: transparent; 
        }
        .button-secondary--active {
            color: $colors.secondary-active;
            outline: none;
            background-color: transparent;
            box-shadow: none;
            AttributeFocused: button-secondary-focused-highlighted;
        }
        .button-secondary--disabled {
            color: $colors.gray03;
            background-color: transparent;
            cursor: auto;
        }
        //BUTTON TERTIARY (OUTLINED)
        .button-tertiary {
            background-color: transparent;
            font-size: $fontSizes.s;
            font-family: $fonts.primary-semibold;
            color: $colors.primary;
            text-transform: uppercase;
            border-style: solid;
            border-width: $borders.extra-small;
            border-color: $colors.border-primary-enabled;
            gx-button-hovered-class: button-tertiary--hover;
            gx-button-focused-class: button-tertiary--focused;
            gx-button-highlighted-class: button-tertiary--active;
            gx-button-disabled-class: button-tertiary--disabled;
        }
        .button-tertiary--hover {
            background-color: rgba(105, 110, 242, 0.1);
        }
        .button-tertiary--focused {
            outline: none;
            outline-width: $borders.small;
            outline-style: solid;
            outline-color: $colors.secondary-enabled;
            outline-offset: -2px;
        }
        .button-tertiary--active {
            border-color: $colors.border-primary-active;
            color: $colors.primary-active;
            box-shadow: none;
            outline: none;
        }
        .button-tertiary--disabled {
            color: $colors.gray03;
            border-color: $colors.border-tertiary-disabled;
            border-style: solid;
            border-width: $borders.extra-small;
            background-color: transparent;
            cursor: auto;
        }
        //BUTTON DESTRUCTIVE
        .button-primary-destructive {
            @include button-primary;
            background-color: $colors.destructive;
            color: $colors.surface;
            gx-button-hovered-class: button-primary-destructive--hover;
            gx-button-focused-class: button-primary-destructive--focused;
            gx-button-highlighted-class: button-primary-destructive--active;
        }
        .button-primary-destructive--hover {
            background-color: #d32f2b;
        }
        .button-primary-destructive--focused {
            background-color: $colors.destructive;
            outline-width: $borders.small;
            outline-style: solid;
            outline-color: $colors.secondary-enabled;
            outline-offset: -2px;
        }
        .button-primary-destructive--active {
            background-color: #a02622;
        }
        .button-secondary-destructive {
            @include button-secondary;
            color: $colors.destructive;
            gx-button-hovered-class: button-secondary-destructive--hover;
            gx-button-focused-class: button-secondary-destructive--focused;
            gx-button-highlighted-class: button-secondary-destructive--active;
        }
        .button-secondary-destructive--hover {
            background-color: #ff665940;
        }
        .button-secondary-destructive--active {
            background-color: transparent;
            color: #a02622;
        }
        .button-secondary-destructive--focused {
            background-color: transparent;
            color: $colors.destructive;
            outline-width: $borders.small;
            outline-style: solid;
            outline-color: $colors.secondary-enabled;
            outline-offset: -2px;
        }
        .button-tertiary-destructive {
            @include button-tertiary;
            color: $colors.destructive;
            border-color: $colors.destructive;
            gx-button-hovered-class: button-secondary-destructive--hover;
            gx-button-focused-class: button-secondary-destructive--focused;
            gx-button-highlighted-class: button-secondary-destructive--active;
        }
        //BUTTON ROUNDED
        .button-rounded {
            background-color: $colors.primary;
            font-size: 0px;
            color: $colors.on-primary;
            border:none;
            border-radius: 50%;
            height: 40px;
            width: 40px;
            padding-block-start: 2px;
            padding-inline-start: 8px;
            min-width: auto;
        }
        .button-rounded--hover {
            background-color: $colors.primary-hover;
        }
        .button-rounded--focused {
            background-color: $colors.primary;
            outline: none;
            border-color: $colors.secondary-enabled;
            border-width: $borders.small;
            border-style: solid;
            padding-inline-start: 6px;
        } 
        .button-rounded--active { 
            background-color: $colors.primary-active;
            box-shadow: none;
            outline: none;
            border: none;
            padding-inline-start: 8px; 
        }
        .button-rounded--disabled {
            background-color: $colors.gray03;
            color: $colors.on-disabled;
            cursor: auto;
        }

        //Auxiliary button
        .button-auxiliary {
            background-color: transparent;
            font-size: 0px;
            color: $colors.on-primary;
            border:none;
            border-radius: $radius.s;
            height: 28px;
            width: 28px;
            min-width: 28px;
            gx-button-hovered-class: button-auxiliary--hover;
            gx-button-focused-class: button-auxiliary--focused;
            gx-button-highlighted-class: button-auxiliary--active;
            gx-button-disabled-class: button-auxiliary--disabled;
        }
        .button-auxiliary--hover {
            background-color: $colors.primary-hover-20;
        }
        .button-auxiliary--focused {
            border:none;
            background-color: transparent;
            outline-width: $borders.small;
            outline-style: solid;
            outline-color: $colors.secondary-enabled;
            outline-offset: -2px;
            color: $colors.primary;
        }
        .button-auxiliary--active {
            color: $colors.secondary-active;
            outline: none;
            background-color: transparent;
            box-shadow: none;
        }
        .button-auxiliary--disabled {
            color: $colors.on-disabled;
            background-color: transparent;
            cursor: auto;
        }
        //Button icon
        .button-icon {
            line-height: 25px;
            cursor: pointer;
        }
        .Button.button-primary.button-icon {
            padding-inline-start: 12px;
        }
        .Button.button-secondary.button-icon {
            padding-inline-start: 10px;
        }
        .Button.button-tertiary.button-icon {
            padding-inline-start: 10px;
        }

        .Button.button-primary.button-icon.icon-only,
        .Button.button-secondary.button-icon.icon-only,
        .Button.button-tertiary.button-icon.icon-only {
            padding-inline-start: 2px;
            padding-inline-end: 2px;
            width: 28px;
            min-width: 28px;
            overflow: hidden;
            font-size: 0px;
        }
    #endregion

    #region Labels
        .attribute-label {
            color: $colors.on-background;
            font-size: $fontSizes.s;
            font-family: $fonts.primary-semibold;
            padding-block-start: 4px;
        }
    #endregion

    #region Textblock
        .heading-01 {
            font-family: $fonts.primary-bold;
            font-size: $fontSizes.xl;
            color: $colors.on-background;
            letter-spacing: 0.25px;
            line-height: 32px;
        }
        .heading-02 {
            @include heading-01;
            font-size: $fontSizes.l;
            letter-spacing: 0.6px;
            line-height: 18px;
        }
        .heading-03 {
            @include heading-01;
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.m;
            letter-spacing: 0.48px;
            line-height: 16px;
        }
        .heading-04 {
            @include heading-01;
            font-size: $fontSizes.s;
            letter-spacing: 0.38px;
            line-height: 13px;
        }
        .TextBlock, .Textblock {
            color: $colors.on-background;
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.s;
        }
    #endregion

    #region Badges
        //tag attributes ("badges")
        .badge {
            gx-label-class: attribute-label; 
            border-radius: 20px;
            padding-inline-start: 20px;
            padding-inline-end: 7px;
            background-repeat: no-repeat;
            background-position: 5px 5px;
            background-size: 8px;
            border-style: solid;
            border-width: 1px;
            font-family: $fonts.primary-regular;
            font-size: 13px;
            color: black;
            white-space: nowrap;
        }
        body[dir="rtl"] [class*="badge-"] {
            background-position: center right 5px;
        }
        .badge-success {
            @include badge;
            background-color: $colors.success-light;        
            border-color: $colors.success-dark;  
            background-image: gx-image(GeneXusUnanimo.dot_green);
            background-position-y: center;
        }
        .Readonlybadge-success{
            @include badge-success;
        }
        .badge-warning {
            @include badge;
            background-color: $colors.warning-light;        
            border-color: $colors.warning-dark;
            background-image: gx-image(GeneXusUnanimo.dot_yellow);
            background-position-y: center;
        }
        .Readonlybadge-warning{
            @include badge-warning;
        }
        .badge-danger {
            @include badge;
            background-color: $colors.error-light;        
            border-color: $colors.error-dark;
            background-image: gx-image(GeneXusUnanimo.dot_red);   
            background-position-y: center;
        }
        .Readonlybadge-danger {
            @include badge-danger; 
        }
        .badge-info {
            @include badge;
            background-color: $colors.primary-hover-20;        
            border-color: $colors.primary;
            background-image: gx-image(GeneXusUnanimo.dot_purple);
            color: $colors.on-background;
            background-position-y: center;
        }
        .Readonlybadge-info {
            @include badge-info;
        }
        .badge-disabled {
            @include badge;
            background-color: $colors.gray02;        
            border-color: $colors.border-gray-03;
            background-image: gx-image(GeneXusUnanimo.dot_gray);
            color: $colors.on-background;
            background-position-y: center;
        }
        .Readonlybadge-disabled {
            @include badge-disabled;
        }
    #endregion

    #region Grid
        .Grid {
            background-color: $colors.form-container-bg;
            font-family: $fonts.primary-bold;
            font-size: $fontSizes.s;
            color: $colors.on-background;
            border-bottom-width: $borders.extra-small;
            border-bottom-style: solid;
            border-bottom-color: $colors.gray01;
            padding-block: 7px;
            padding-inline-start: $spacing.inset-s;
            padding-inline-end: $spacing.inset-s;
            cursor: pointer;
        }
    #endregion

    #region Grid Row
        .grid-row {
            text-align: start;
            padding-inline-start: $spacing.inset-s;
            padding-inline-end: $spacing.inset-s;
            border-bottom-width: $borders.extra-small;
            border-bottom-style: solid;
            border-bottom-color: $colors.gray01;
        }
        .grid-row-highlight {
            text-align: start;
            padding-inline-start: $spacing.inset-s;
            padding-inline-end: $spacing.inset-s;
            border-bottom-width: $borders.extra-small;
            border-bottom-style: solid;
            border-bottom-color: $colors.gray01;
            cursor: pointer;
        }
        //selected class when Grid's AllowSelection is true
        .gx-row-selected {
            background-color: $colors.row-active;
            -webkit-box-shadow: -3px 0px 0px 0px $colors.primary; 
            box-shadow: -3px 0px 0px 0px $colors.primary;
        }
        .gx-grid__row-delete, .gx-grid__row-add { 
            content: gx-image(GeneXusUnanimo.minus_light);
            width: 18px;
            padding-top: 5px;
        }
        .gx-grid__row-add {
            content: gx-image(GeneXusUnanimo.plus_light);
        }
        .RowDeleted {
            text-decoration: line-through;
        }
    #endregion

    #region Grid Column
        .column {
            width: 100%;  
            padding-inline-start: $spacing.inset-s;
            padding-inline-end: $spacing.inset-s;
            border-bottom-width: 1px;
            border-bottom-color: $colors.gray01;
            border-bottom-style:solid;
            gx-grid-column-header-class: column;
        } 
        .column, .column-optional {
            overflow: hidden; 
            text-overflow: ellipsis;
            color: $colors.on-background;
        }
        .sort-ico--asc {
            content: gx-image(GeneXusUnanimo.arrow_asc); 
        }
        .sort-ico--desc {
            content: gx-image(GeneXusUnanimo.arrow_desc);
        }
        @media screen and (max-width: 767px) {
            .column-optional {
               display: none; 
            }
        }
    #endregion

    #region Form Container
        .card {
            background-color: $colors.form-container-bg;
            border-radius: $radius.xl;
            box-shadow: $shadows.xxs;
        }
        .card-body {
            padding: $spacing.inset-m;
        }
        .card-heading {
            box-shadow: 0px 1px 1px $colors.gray01;
            padding: $spacing.inset-m;
            font-family: $fonts.primary-bold;
            font-size: $fontSizes.s;
            letter-spacing: $spacing.letter-spacing-s;
            color: $colors.on-background;
        }
        .card-footer {
            box-shadow: 0px -1px 1px $colors.gray01;
            padding: $spacing.inset-m;
        }
    #endregion

    #region Tab
        .tab-item {
            font-family: $fonts.primary-semibold;
            font-size: $fontSizes.s;
            letter-spacing: 0.4px;
            text-decoration: none;
            color: $colors.surface-negative;
            padding: 5px;
            gx-tab-page-hovered-class: tab-item--hover;
            gx-tab-page-selected-class: tab-item--selected;
        }
        .tab-item--hover {
            border-bottom-color: $colors.primary-hover;
        }
        .tab-item--selected {
            font-family: $fonts.primary-semibold;
            font-size: $fontSizes.s;
            letter-spacing: 0.4px;
            border-bottom-color: $colors.primary-active;
            border-bottom-style: solid;
            border-bottom-width: 3px;
            text-decoration: none;
            color: $colors.on-background;
        }
    #endregion

    #region Master Page
        .HeaderContainer {
            background-color: $colors.header-bg;
            height: 60px;
            border-bottom-width: 2px;
            border-bottom-style: solid;
            border-bottom-color: $colors.header-separator-bg;
            margin: 0 -15px;
            margin-bottom: $spacing.stack-xxl;
        }
        .header__title {
            @include heading-01;
            color: $colors.on-secondary;
        }
        .header__logo {
            max-width: 100px;
        }
        .sidebar__toggle-ico {
            margin-top: 1px;
            display: none;
            margin-inline-end: $spacing.inset-s;
        }
        .sidebar__toggle-ico:hover {
            cursor: pointer;
        }
        @media screen and (max-width: 767px) {
            .header__title {
                font-size: $fontSizes.m;
            }
            .header__logo {
                max-width: 60px;
            }
            .sidebar__toggle-ico {
                display: block;
            }
            .HeaderContainer {
                margin-bottom: $spacing.stack-l;
            }
        }
    #endregion

    //Utility classes
    #region Utils
        #region Spacing
            //stack
            .stack-top-m {
                margin-top: $spacing.stack-m;
            }
            .stack-top-l {
                margin-top: $spacing.stack-l;
            }
            .stack-top-l {
                margin-top: $spacing.stack-l;
            }
            .stack-top-xl {
                margin-top: $spacing.stack-xl;
            }
            .stack-top-xxl {
                margin-top: $spacing.stack-xxl;
            }
            .stack-top-xxxl {
                margin-top: $spacing.stack-xxxl;
            }
            .stack-top-xxxxl {
                margin-top: $spacing.stack-xxxxl;
            }
            .stack-bottom-m {
                margin-bottom: $spacing.stack-m;
            }
            .stack-bottom-l {
                margin-bottom: $spacing.stack-l;
            }
            .stack-bottom-xl {
                margin-bottom: $spacing.stack-xl;
            }
            .stack-bottom-xxl {
                margin-bottom: $spacing.stack-xxl;
            }
            .stack-bottom-xxxl {
                margin-bottom: $spacing.stack-xxxl;
            }
            .stack-bottom-xxxxl {
                margin-bottom: $spacing.stack-xxxxl;
            }
            //inline
            .inline-left-l {
                margin-inline-start: $spacing.inline-l;
            }
            .inline-left-xl {
                margin-inline-start: $spacing.inline-xl;
            }
            .inline-left-xxl {
                margin-inline-start: $spacing.inline-xxl;
            }
            .inline-left-xxxl {
                margin-inline-start: $spacing.inline-xxxl;
            }
            .inline-right-l {
                margin-inline-end: $spacing.inline-l;
            }
            .inline-right-xl {
                margin-inline-end: $spacing.inline-xl;
            }
            .inline-right-xxl {
                margin-inline-end: $spacing.inline-xxl;
            }
            .inline-right-xxxl {
                margin-inline-end: $spacing.inline-xxxl;
            }
            //inset
            .inset-s {
                padding: $spacing.inset-s;
            }
            .inset-m {
                padding: $spacing.inset-m;
            }
            .inset-l {
                padding: $spacing.inset-l;
            }
        #endregion

        #region Sizing
            .w-100 {
                width: 100%;
            }
            .h-100 {
                height: 100%;
            }
        #endregion

        #region Background
            .bg-white {
                background: $colors.surface;
            }
        #endregion

        #region Font Color
            .text-transparent {
                color: transparent;
            }
            .text-black {
                color: rgba(0, 0, 0, 1);
            }
            .text-white {
                color: rgba(255, 255, 255, 1);
            }
            .text-gray-500 {
                color: rgba(107, 114, 128, 1);
            }
        #endregion

        #region Font Weight
            .light {
                font-family: $fonts.primary-light;
                font-weight: 300;
            }
            .normal {
                font-family: $fonts.primary-regular;
            }
            .bold {
                font-family: $fonts.primary-bold;
            }
        #endregion

        #region Margin
            .mt-0 {
                margin-block-start: 0px;
            }
            .mr-0 {
                margin-inline-end: 0px;
            }
            .mb-0 {
                margin-block-end: 0px;
            }
            .ml-0 {
                margin-inline-start: 0px;
            }
        #endregion
    #endregion

}

tokens UnanimoControls (color-scheme:dark|[light])
{
    //COLORS 
    @color-scheme = light {
        #colors {
            mask-bg: #0000001a;
            //0.1 opacity
        }
    }
    @color-scheme = dark {
        #colors { 
            mask-bg: #00000080;
            //0.5 opacity
        }
    }
}

styles UnanimoControls
{
    @import GeneXusUnanimo.Unanimo;

    #region Dropdown UC
        .dd-overlay {
            position: fixed;
            display: none;
            width: 100%;
            height: 100%;
            top: 0;
            left: 0;
            right: 0;
            bottom: 0;
            background-color: rgba(0,0,0,0.0);
            z-index: 1;
        }
        .dd-overlay--visible {
            display: block;
        }
        .dd-vertical-separator {
            border-inline-start: 1px solid $colors.primary;
            height: 32px;
            padding-inline-end: 15px;
        }
        .dd-avatar{
            border-radius: 50px;
            height: 32px;
            width: 32px;
            object-fit:cover;
        }
        .dd-avatar-container {
            cursor: pointer;
            height: 32px;
        }
        .dd-flex-container {
            display: flex;
            align-items: center;
            gap: $spacing.inline-xl;
            line-height: 16px;
        }
        .dropdown {
            position: relative;
            height: 32px;
        }
        .dropdown-content {
            display: none;
            position: absolute;
            background: $colors.header-bg;
            min-width: 160px;
            border-radius: 6px;
            box-shadow: 0px 3px 4px 0px rgba(0, 0, 0, 0.14),
            0px 3px 3px -2px rgba(0, 0, 0, 0.12),
            0px 1px 8px 0px rgba(0, 0, 0, 0.2);
            z-index: 2;
            padding-block: 3px;
            top: 32px;
            inset-inline-end: 0px;
            //clear defaults for ul element
            margin-block: 0px;
            padding-inline-start: 0px;
            list-style-type: none;
        }
        .dropdown-content:hover {
            display: block;
        }
        .dropdown-content .dd-text-container {
            cursor: default;
            text-align: unset;
            padding-inline-start: 26px;
        }
        .dd-option {
            color: $colors.on-secondary;
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.s;
            height: 28px;
            letter-spacing: 0.25px;
            line-height: 16px;
            text-align: start;
            padding-block: 6px;
            margin-bottom: 0px !important;
        }
        .dd-option-container {
            padding-block: 3px;
        }
        .dd-option-container:hover {
            background: $colors.item-hover;
            cursor: pointer;
        }
        .dd-option-icon {
            filter: invert(41%) sepia(32%) saturate(3954%) hue-rotate(221deg) brightness(99%) contrast(92%);
            padding-block-start: 2px;
            padding-inline-start: 8px;
            vertical-align: middle;
        }
        .dd-text-container {
            text-align: center;
            cursor: pointer;
            padding-inline-end: 15px;
            min-height: 32px;
            display: grid;
            align-items: center;
        }
        .dd-text-container[hidden] {
            display: none;
        }
        .dd-username {
            color: $colors.primary;
            font-family: $fonts.primary-semibold;
            font-size: 14px;
            letter-spacing: 0.25px;
            text-align: center;
        }
        .dd-companyname {
            color: $colors.on-secondary;
            font-family: $fonts.primary-regular;
            font-size: 12px;
            letter-spacing: 0.2px;
            line-height: 13px;
        }
        .dropdown-content a {
            text-decoration: none;
            display: block;
        }
        .dropdown-content a:hover {
            background: $colors.item-hover;
            border-radius: 0px;
            color: $colors.on-primary;
        }
        .box3:hover {
            cursor: pointer;
        }
        .box3:hover .dropdown-content {
            display: block;
        }
        .dropdown-content--visible {
            display: block;
        }
    #endregion

    #region Slider UC
        .slider-container {
            position: relative;
            margin-top: $spacing.stack-l;
            margin-bottom: $spacing.stack-l;
        }
        .slider {
            width: calc(100% - 3px);
            -webkit-appearance: none;
            height: 4px;
            background: $colors.gray02 !important;
            outline: none;
            border-radius: 6px;
            -webkit-transition: .2s;
            transition: opacity .2s;
            //default
            -webkit-writing-mode: horizontal-tb !important;
            text-rendering: auto;
            display: inline-block;
            text-align: start;
        }
        .slider:hover {
            opacity: 1;
        }
        .slider-container input[type=range][disabled] + .slider-value {
            color: $colors.primary-disabled;
        }
        .slider::-webkit-slider-thumb {
            -webkit-appearance: none;
            width: 14px;
            height: 14px;
            border-radius: 100%;
            cursor: pointer;
            background-color: $colors.on-secondary;
            box-shadow: $shadows.m;
        }
        .slider:focus::-webkit-slider-thumb {
            background: $colors.primary;
        }
        //FF
        .slider::-moz-range-thumb {
            width: 14px;
            height: 14px;
            background: $colors.surface;
            cursor: pointer;
            border-radius: 100%;
            border: none;
            box-shadow: $shadows.m;
        }
        .slider:focus::-moz-range-thumb {
            background: $colors.primary;
        }
        .slider::-moz-range-progress {
            background: $colors.primary;
        }
        .slider-value {
            font-family: $fonts.primary-bold;
            font-size: $fontSizes.s;
            color: $colors.primary;
            background: transparent;
            padding-block: 4px;
            position: absolute;
            border-radius: 4px;
            top: -20px;
            inset-inline-start: 50%;
            transform: translateX(-50%);
        }
    #endregion

    #region Switch UC
        .switch-container {
            margin-top: 12px;
        }
        .switch-container > input[type="checkbox"] {
            display: none;   
        }
        .switch-container > label {
            cursor: pointer;
            height: 0px;
            position: relative; 
            width: 40px;
            color: transparent;
        }
        .switch-container > label::before {
            background: $colors.gray03;
            box-shadow: inset 0px 0px 10px rgba(0, 0, 0, 0.5);
            border-radius: 8px;
            content: '';
            height: 12px;
            margin-top: -6px;
            position:absolute;
            transition: all 0.4s ease-in-out;
            width: 40px;
        }
        .switch-container > label::after {
            background: rgb(255, 255, 255);
            border-radius: 16px;
            box-shadow: 0px 0px 5px rgba(0, 0, 0, 0.3);
            content: '';
            height: 24px;
            inset-inline-start: -4px;
            margin-top: -8px;
            position: absolute;
            top: -4px;
            transition: all 0.3s ease-in-out;
            width: 24px;
        }
        .switch-container > input[type="checkbox"]:checked + label::before {
            background: $colors.primary-enabled;
            opacity: 0.5;
        }
        .switch-container > input[type="checkbox"]:checked + label::after {
            background: $colors.primary-active;
            inset-inline-start: 20px;
        }
        //disabled
        .switch-container > input[type="checkbox"]:disabled + label::before {
            background: $colors.gray03; 
            cursor: auto;
        }
        .switch-container > input[type="checkbox"]:disabled + label::after {
            background: $colors.gray03;
            cursor: auto;
        }
        //focus
        .switch-container:focus {
            outline: none;
        }
        .switch-container:focus label:after{
            box-shadow: 0px 0px 1px 3px $colors.secondary;
        }

    #endregion          

    #region Alert UC
        .alert {
            display: inline-flex;
            align-items: center;
            height: 60px;
            padding-inline-start: $spacing.inline-xxl;
            margin-bottom: $spacing.stack-xl;
            box-shadow: $shadows.m;

        }
        //show alert always fixed to bottom, no matter of the scroll
        .alert-fixed {
            position: fixed;
            top: 90vh;
            z-index: 10;
            inset-inline-start: 50%;
            transform: translateX(-50%);
        }
        .alert-close {
            background: transparent;
            border: none;
            font-family: $fonts.primary-regular;
            font-size: 30px;
            cursor: pointer;
            color: $colors.on-alert;
        }
        .alert-title {
            font-family: $fonts.primary-bold;
            font-size: $fontSizes.s;
            letter-spacing: 0.38px;
            text-transform: uppercase;
            line-height: 16px;
            padding-inline-start: $spacing.inline-l;
        }
        .alert-message {
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.s;
            letter-spacing: 0.25px;
            line-height: 16px;
            padding-inline-start: $spacing.inline-l;
        }
        .alert-badge {
            display: flex;
            justify-content: center;
            align-items: center;
            background-color: $colors.primary;
            border-radius: 50%;
            padding: 2px;
            width: 20px;
            height: 20px;
            box-shadow: $shadows.l;
            position: relative;
            top: -25px;
            inset-inline-end: -5px;
        }
        .alert-badge-text {
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.s;
            color: $colors.on-primary;
        }
        .alert-multiple {
            box-shadow: 5px -5px 0px 0px #ececec, 10px -10px 0px 0px #f7f7f7;
        } 
        .alert-info {
            @include icon-info;
            background-color: $colors.gray01;
            border-inline-start: solid 4px;
            border-inline-start-color: $colors.primary;
        }
        .alert-success {
            @include icon-success;
            background-color: $colors.success-light;
            border-inline-start: solid 4px;
            border-inline-start-color: $colors.success-dark;
        }
        .alert-warning {
            @include icon-warning;
            background-color: $colors.warning-light;
            border-inline-start: solid 4px;
            border-inline-start-color: $colors.warning-dark;
        }
        .alert-error {
            @include icon-error;
            background-color: $colors.error-light;
            border-inline-start: solid 4px;
            border-inline-start-color: $colors.error-dark;
        }
        .icon-info {
            background-image: gx-image(GeneXusUnanimo.info_ico_purple);
            background-size: 25px;
            background-repeat: no-repeat;
            background-position: 15px, center;
        }
        .icon-success {
            background-image: gx-image(GeneXusUnanimo.success_ico_green);
            background-size: 25px;
            background-repeat: no-repeat;
            background-position: 15px, center;
        }
        .icon-warning {
            background-image: gx-image(GeneXusUnanimo.warning_ico);
            background-size: 25px;
            background-repeat: no-repeat;
            background-position: 15px, center;
        }
        .icon-error {
            background-image: gx-image(GeneXusUnanimo.error_ico);
            background-size: 25px;
            background-repeat: no-repeat;
            background-position: 15px, center;
        }
        html[gx-data-color-scheme="dark"] div[class*="alert"]{
            background-color: $colors.elevation-03;
            color: $colors.on-alert;
        }
    #endregion

    #region Icon UC
        ch-icon[data-event] {
            cursor: pointer;
        }
    #endregion

    #region Select UC
        .ch-select::part(collapse-icon){
            -webkit-mask: gx-image(GeneXusUnanimo.arrow_asc);
            -webkit-mask-size: 20px;
            -webkit-mask-repeat: no-repeat;
            background-color: $colors.on-secondary;
            width: 20px;
            height: 20px;
        }
        .ch-select::part(text) {
            color: $colors.on-secondary;
            font-size: 12px;
        }
        .ch-select::part(select-box) {
            background-color: $colors.secondary-enabled;
            color: $colors.on-secondary; 
            border-radius: $radius.m;
        }
        .ch-select::part(select-options) {
            background-color: $colors.secondary-enabled;
            color: $colors.on-secondary; 
            border-radius: $radius.m;
        }
        .option::part(option-text) {
            color: $colors.on-secondary; 
            font-size: 12px;
        }
        .option[disabled]::part(option-text) {
            color: unset;
        }
        .option::part(option-box):hover {
            background-color: $colors.secondary-hover;
        }
        .option[aria-selected="true"]::part(option-box) {
            background-color: $colors.secondary-active;
        }
        .ch-select--on-surface {
            --font-size: 12px;
            --icon-size: 15px;
            --background-color: $colors.surface;
            --text-color: $colors.surface-negative; 
            --item-hover-color: $colors.primary-hover-20; 
            --item-active-color: $colors.primary-hover-20; 
            --icon-color: $colors.surface-negative; 
            --arrow-color: $colors.on-secondary; 
        }
        .ch-select--on-surface::part(collapse-icon){
            -webkit-mask: gx-image(GeneXusUnanimo.arrow_asc);
            -webkit-mask-size: 20px;
            -webkit-mask-repeat: no-repeat;
            background-color: $colors.surface-negative;
            width: 20px;
            height: 20px;
        }
        //header select
        .dd-container .ch-select {
            --justify-content: flex-end;
        }
    #endregion

    #region Sidebar UC
        .ch-sidebar {
            --menu-background-color: $colors.sidebar-bg;
            --text-color: $colors.on-secondary;
            --item-hover-color: $colors.item-hover;
            --item-active-color: $colors.item-active;
            --first-list-icon-color: $colors.on-secondary;
            --first-list-arrow-color: $colors.on-secondary;
            --second-list-arrow-color: $colors.primary;
            --footer-line-color: $colors.primary;
            --indicator-color: $colors.on-secondary;
            --scrollbar-track: $colors.gray02;
            --scrollbar-thumb: $colors.secondary-active;
            --title-text-transform: uppercase;
            --first-list-text-transform: unset;
            --second-list-text-transform: unset;
            --third-list-text-transform: unset;
        }
        .ch-sidebar::part(menu) {
            box-shadow: $shadows.xl;
        }
        //sidebar collapse icon
        .collapse-item-icon {
            -webkit-mask: gx-image(GeneXusUnanimo.arrow_left);
            -webkit-mask-size: 20px;
            -webkit-mask-repeat: no-repeat;
            background-color: $colors.on-secondary;
            width: 20px;
            height: 20px;
        }
        .ch-sidebar::part(collapse-menu-icon){
            @include collapse-item-icon;
        }
        body[dir="rtl"] .ch-sidebar::part(collapse-menu-icon){
            @include collapse-item-icon;
            -webkit-mask: gx-image(GeneXusUnanimo.arrow_right);
            -webkit-mask-size: 20px;
        }
        //item collapse icon
        .ch-sidebar ch-sidebar-menu-list-item::part(collapse-item-icon){
            -webkit-mask: gx-image(GeneXusUnanimo.arrow_asc);
            -webkit-mask-size: 20px;
            -webkit-mask-repeat: no-repeat;
            background-color: $colors.on-secondary;
            width: 20px;
            height: 20px;
        }
        //second level item collapse icon
        .ch-sidebar ch-sidebar-menu-list-item::part(collapse-item2-icon){
            @include collapse-item-icon;
            -webkit-mask: gx-image(GeneXusUnanimo.arrow_right);
            -webkit-mask-size: 20px;
            background-color: $colors.primary;
        }
        body[dir="rtl"] .ch-sidebar ch-sidebar-menu-list-item::part(collapse-item2-icon){
            @include collapse-item-icon;
            -webkit-mask: gx-image(GeneXusUnanimo.arrow_left);
            -webkit-mask-size: 20px;
            background-color: $colors.primary;
        }
    #endregion

    #region Treeview UC
        .ch-treeview-item {
            --text-color: $colors.surface-negative;
            --font-weight: normal;
            --font-size: $fontSizes.s;
            --item-hover-color: $colors.primary-hover-20;
            --item-active-color: $colors.primary-hover-20;
            --guide-color: $colors.surface-negative;
        }
        .ch-treeview-item ch-tree-item::part(expand-icon){
            -webkit-mask: gx-image(GeneXusUnanimo.plus);
            -webkit-mask-size: 16px;
            -webkit-mask-repeat: no-repeat;
            background-color: $colors.surface-negative;
            background-position: center;
            width: 16px;
            height: 16px; 
        }
        .ch-treeview-item ch-tree-item::part(collapse-icon){
            -webkit-mask: gx-image(GeneXusUnanimo.minus);
            -webkit-mask-size: 16px;
            -webkit-mask-repeat: no-repeat;
            background-color: $colors.surface-negative;
            width: 16px;
            height: 16px; 
        }
    #endregion

    #region Step UC
        .ch-step {
            --text-color: $colors.surface-negative;
            --font-weight: bold;
            --font-size: $fontSizes.s;
            --item-color: $colors.gray01;
            --item-active-color: $colors.primary;
            --line-color: $colors.gray01;
        }
        .ch-step-done {
            --item-color: $colors.primary-active;
            --line-color: $colors.primary-active;
        }
        .item--selected {
            --item-color: $colors.primary;
            --line-color: $colors.primary;
        }
        .ch-step::part(item-icon){
            -webkit-mask: gx-image(GeneXusUnanimo.dot_gray);
            -webkit-mask-size: 12px;
            -webkit-mask-repeat: no-repeat;
            background-color: $colors.surface; 
            width: 12px;
            height: 12px; 
        }
    #endregion

    #region Grid UC
        ch-grid {
            display: inline-block;
        }
        ch-grid::part(settings-mask) {
            background-color: $colors.mask-bg;
        }
        .filter-input {
            border-width: 1px;
            min-height: 28px;
            max-width: 100%;
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.s;
            padding-inline-start: $spacing.inset-s;
            padding-inline-end: $spacing.inset-s;
            padding-block: 0px;
            border-color: $colors.gray04;
            color: $colors.on-background;
            background-color: $colors.attribute-bg;
            border-radius: $radius.l;
        }
        .grid-columnset {
            font-family: $fonts.primary-bold;
            font-size: $fontSizes.s;
            color: $colors.on-background;
            background-color: $colors.form-container-bg;
            border-bottom-width: $borders.extra-small;
            border-bottom-style: solid;
            border-bottom-color: $colors.border-gray-01;
            padding-block: 7px;
            padding-inline-start: $spacing.inset-s;
            padding-inline-end: $spacing.inset-s;
            cursor: default;
        }
        .grid-cell {
            align-items: center;
            padding-inline-start: $spacing.inset-s;
            padding-inline-end: $spacing.inset-s;
        }
        //Angular in-grid controls
        .in-grid-field {
            border: none;
            margin: 0px;
            padding: 0px;
            background-color: transparent;
        }
        .grid-cell gx-edit[readonly="true"] {
            @include in-grid-field;
            font-size: $fontSizes.s;
        }
        .grid-cell gx-checkbox[readonly="true"] {
            @include in-grid-field;
        }
        .grid-cell .gx-image-container.Attribute {
            @include in-grid-field;
        }
        .grid-cell gx-form-field {
            padding-block: 11px;
        }
        .grid-row {
            text-align: start;
            padding-inline-start: $spacing.inset-s;
            padding-inline-end: $spacing.inset-s;
            border-bottom-width: $borders.extra-small;
            border-bottom-style: solid;
            border-bottom-color: $colors.gray01;
        }
        .gx-row-selected {
            background-color: rgba(105, 110, 242, 0.2);
            -webkit-box-shadow: -3px 0px 0px 0px $colors.primary; 
            box-shadow: -3px 0px 0px 0px $colors.primary;
        }
        .grid-row-highlight {
            text-align: start;
            padding-inline-start: $spacing.inset-s;
            padding-inline-end: $spacing.inset-s;
            border-bottom-width: $borders.extra-small;
            border-bottom-style: solid;
            border-bottom-color: $colors.gray01;
            cursor: pointer;
        }
        .grid-row-highlight:hover {
            background-color: $colors.gray01;
        }
        .grid-column {
            padding-inline-start: $spacing.inset-s;
            padding-inline-end: $spacing.inset-s;
        }
        .grid-column::part(bar) {
            flex: 1;
        }
        .grid-column::part(bar)::after {
            content: '';
            order: 2;
        }
        .grid-column::part(bar-settings) {
            width: 20px;
            height: 20px;
            visibility: hidden;
        }
        .grid-column:hover::part(bar-settings) {
            visibility: visible;
        }
        .grid-column::part(bar-settings):hover {
            cursor: pointer; 
        }
        .grid-column::part(bar-settings-button) {
            border: none;
            padding: 0;
            background-color: transparent;
            width: 20px;
            height: 20px;
        }
        .grid-column::part(bar-settings-button)::before {
            content: '';
            background-image: gx-image(GeneXusUnanimo.filter_outlined_light);
            background-size: contain;
            background-repeat: no-repeat;
            background-position: center;
            display: block;
            width: 20px;
            height: 20px;
        }
        .grid-column::part(bar-settings-button):hover {
            cursor: pointer;
        }
        .grid-column-filtering::part(bar-settings) {
            visibility: visible;
        }
        .grid-column-filtering::part(bar-settings-button):before {
            content: '';
            background-image: gx-image(GeneXusUnanimo.filter_applied);
            background-size: contain;
            background-repeat: no-repeat;
            background-position: center;
            display: block;
            width: 20px;
            height: 20px;
        }
        .grid-column::part(bar-name-text):hover {
            cursor: pointer;
        }
        .grid-column::part(bar-name-icon):hover {
            cursor: pointer;
        }
        .grid-column::part(bar-resize) {
            margin-inline-start: auto;
            width: 20px;
            height: 20px;
            visibility: hidden;
            display: block;
            align-self: auto;
        }
        .grid-column:hover::part(bar-resize) {
            visibility: visible;
        }
        .grid-column::part(bar-resize-split) {
            content: unset;
            background-image: gx-image(GeneXusUnanimo.resize_column_light);
            background-repeat: no-repeat;
            background-position: center center;
            background-size: 22px;
        }
        .grid-column::part(bar-sort):not([hidden]):hover {
            cursor: pointer;
        }
        .grid-column::part(bar-sort-ascending) {
            content: gx-image(GeneXusUnanimo.arrow_asc_light);
        }
        .grid-column::part(bar-sort-descending) {
            content: gx-image(GeneXusUnanimo.arrow_desc_light);
        }
        .grid-column-filter::part(main) {
            display: flex;
            flex-direction: column;
            gap: $spacing.inline-l;
            padding: 0px;
            border: none;
        }
        .grid-column-filter::part(label greater) {
            font-family: $fonts.primary-regular;
            display: flex;
            flex-direction: column;
        }
        .grid-column-filter::part(label less) {
            font-family: $fonts.primary-regular;
            display: flex;
            flex-direction: column;
        }
        .grid-column-filter::part(footer) {
            display: flex;
            gap: $spacing.inline-xl;
            justify-content: flex-end;
            padding-block-start: $spacing.stack-xl;
        }
        .grid-column-filter::part(field greater) {
            @include filter-input;
        }
        .grid-column-filter::part(field less) {
            @include filter-input;
        }
        .grid-column-filter::part(field equal) {
            @include filter-input;
        }
        .grid-column-filter::part(button reset) {
            @include Button button-tertiary;
        }
        .grid-column-filter::part(button reset):hover {
            cursor: pointer;
        }
        .grid-column-filter::part(button apply) {
            @include Button button-primary;
        }
        .grid-column-filter::part(button apply):hover {
            cursor: pointer;
        }
        .grid-cell img{
            position: relative;
            max-width: 50px;
            object-fit: scale-down;
            padding-block: 2px;
        }
        .Grid::part(footer), .ww__grid::part(footer) {
            display: flex;
            align-items: center;
        }
        //grid settings window
        .Grid::part(settings-window), .ww__grid::part(settings-window) {
            background: $colors.overlay-bg;
            padding: $spacing.inset-m;
            border-radius: $radius.xl;
            border: none;
            box-shadow: $shadows.s;
        }
        .Grid::part(settings-header), .ww__grid::part(settings-header){
            display: flex;
            gap: 16px;
            justify-content: space-between;
            align-items: center;
            margin-bottom: $spacing.stack-l;
        }
        .Grid::part(settings-caption), .ww__grid::part(settings-caption) {
            color: $colors.on-background;
            font-family: $fonts.primary-bold;
            font-size: $fontSizes.s;
            letter-spacing: $spacing.letter-spacing-s;
            line-height: 18px;
            text-transform: uppercase;
        }
        .Grid::part(settings-close), .ww__grid::part(settings-close) {
            @include button-close;
            background-position: center;
            margin-bottom: 0px;
        }
        .Grid::part(settings-close):hover, .ww__grid::part(settings-close):hover {
            cursor: pointer;
        }
        .Grid::part(settings-columns-item), .ww__grid::part(settings-columns-item) {
            padding-block: $spacing.stack-s;
            font-family: $fonts.primary-regular;
        }
        .Grid::part(settings-columns-label), .ww__grid::part(settings-columns-label) {
            display: flex;
        }
        .Grid::part(settings-columns-label):hover, .ww__grid::part(settings-columns-label):hover {
            cursor: pointer;
        }
        //column filters window
        .grid-column::part(settings-mask) {
            background-color: $colors.mask-bg;
        }
        .grid-column::part(settings-window) {
            background: $colors.overlay-bg;
            padding: $spacing.inset-m;
            border-radius: $radius.xl;
            border: none;
            box-shadow: $shadows.s;
        }
        .grid-column::part(settings-header){
            display: flex;
            justify-content: space-between;
            align-items: center;
            gap: $spacing.inline-xl;
            margin-block-end: $spacing.stack-l;
        }
        .grid-column::part(settings-caption) {
            color: $colors.on-background;
            font-family: $fonts.primary-bold;
            font-size: $fontSizes.s;
            letter-spacing: $spacing.letter-spacing-s;
            line-height: 18px;
        }
        .grid-column::part(settings-close) {
            @include button-close;
            background-position: center;
            margin-block-end: 0px;
        }
        .grid-column::part(settings-close):hover {
            cursor: pointer;
        }
        .grid-column fieldset {
            border: none;
            margin: 0;
            padding: 0;
        }
        .grid-column caption {
            color: $colors.gray03;
            font-family: $fonts.primary-regular;
        }
        .grid-column input {
            border-width: 1px;
            min-height: 28px;
            max-width: 100%;
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.s;
            padding-inline-start: $spacing.inset-s;
            padding-inline-end: $spacing.inset-s;
            border-color: $colors.gray04;
            color: $colors.on-background;
            background-color: $colors.attribute-bg;
            border-radius: $radius.l;
        }
        .grid-column input:focus {
            border-color: $colors.secondary-enabled;
            box-shadow: 0px 0px 0px 1px #13142c;
        }
        .gx-grid-paging-bar {
            padding-inline-end: $spacing.inset-s;
        }
        .grid-actionbar-footer {
            display: flex;
            column-gap: $spacing.inset-s;
            align-items: center;
            margin-inline-end: auto;
            padding-inline-start: $spacing.inset-s;
        }
        //grid footer buttons
        .button-refresh {
            content: gx-image(GeneXusUnanimo.refresh);
        }
        .button-refresh:hover {
            cursor: pointer;
            background-color: $colors.primary-hover-20;
        }
        .button-settings {
            content: gx-image(GeneXusUnanimo.settings);
        }
        .button-settings:hover {
            cursor: pointer;
            background-color: $colors.primary-hover-20;
        }
        .button-close {
            background-repeat: no-repeat;
            background-image: gx-image(GeneXusUnanimo.filter);
            border-width: 0;
            color: transparent;
            z-index: 2;
            background-color: $colors.alt-surface;
            width: 20px;
            height: 20px;
            padding: 0px;
            margin-block-end: 20px;
            background-color: $colors.overlay-bg;
            background-image: gx-image(GeneXusUnanimo.close_ico);
        }
        //fede
        input[type="date"] {
            color-scheme: dark;
        }
    #endregion
}

 tokens UnanimoMobile (color-scheme:light|dark)
{
    @color-scheme = light {
        #colors
        {        
            accent: #f3f6fd;
            text-color: #3d4854;
        }
    }

    @color-scheme = dark {
        #colors
        {        
            accent: #242426;
            text-color: #ffffff;
        }
    }
}

styles UnanimoMobile {
    @import GeneXusUnanimo.Unanimo;

    #region Application
        .Application {
            gx-primary-color: $colors.primary;
            gx-primary-color-dark: $colors.accent;
            gx-accent-color: $colors.primary;
            gx-action-tint-color: $colors.primary;
        }
        .ApplicationBars {
            background-color: $colors.accent;
            font-family: $fonts.primary-bold;
            color: $colors.surface-negative;
        }
    #endregion

    #region Menu
        .Menu {
            gx-grid-class: Grid;
            gx-tab-class: Tab;
        }
        .MenuItem {
            color: $colors.text-color;
        }
    #endregion

    #region Attribute
        .Attribute {
            gx-label-class: attribute__label;
            gx-focused-class: attribute--focused;
            gx-readonly-class: attribute--readonly;
            border-style: solid;
            border-color: #8592A6; //change to token when defined
            border-width: 1dip;
            border-radius: 4dip;
            margin-left: 16dip;
            margin-right: 16dip;
            margin-bottom: 8dip;
            background-color: $colors.surface;
            padding-left: 8dip;
            padding-right: 8dip;
            gx-show-edit-text-line: false;
            color: $colors.text-color;
            gx-invite-message-color: #8592A6; //change to token when defined
            font-size: 16dip;
            font-family: $fonts.primary-regular;
        }
        .attribute--focused {
            border-color: $colors.border-primary-enabled;
        }
        .attribute--error {
            @include Attribute;
            border-color: $colors.border-error;
        }
        .AttributeTitle {
            font-size: 16dip;
            font-family: $fonts.primary-regular;
            color: $colors.on-background;
            padding-left: 10dip;
        }
        .AttributeSubTitle {
            font-size: 13dip;
            font-family: $fonts.primary-regular;
            color: $colors.gray03;
            padding-left: 10dip;
        }
        .attribute-checkbox {
            @include Attribute;
            border-style: none;
            padding-left: 8dip;
        }  
        .attribute-radiobutton {
            @include Attribute;
            border-style: none;
            padding-left: 8dip;
        }
        .attribute-date {
            @include Attribute;
            margin-bottom: 7dip;
        }
        .attribute-select__item {
            border-style: none;
        }
        //readonly
        .attribute--readonly {
            gx-label-class: ww__attribute__label--readonly;
            color: $colors.text-color;
            border-style: none;
            padding-top: 8dip;
            margin-bottom: 0dip;
            margin-left: 16dip;
            margin-right: 16dip;
        }
        //disabled
        .attribute--disabled {
            @include Attribute;
            gx-label-class: attribute__label--disabled; 
            color: $colors.gray03;
            border-color: $colors.border-gray-01;
        }
        .attribute-checkbox--disabled {
            @include attribute--disabled;
            border-style: none;
            padding-left: 8dip;
        }
        .attribute-radiobutton--disabled {
            @include attribute--disabled;
            border-style: none;
            padding-left: 8dip;
        }
        .attribute-date--disabled {
            @include attribute--disabled;
            margin-bottom: 7dip;
        }
        //work with
        .ww__attribute--readonly { 
            @include Attribute;
            gx-label-class: ww__attribute__label--readonly;
            color: $colors.text-color;
            padding-top: 8dip;
            margin-bottom: 0dip;
            margin-left: 0dip;
            margin-right: 0dip;
            border-style: none; 
        }
        //semantic domains class
        .LinkAttribute {
            //@include ww__attribute--readonly; -- change to this when working
            gx-label-class: ww__attribute__label--readonly;
            color: $colors.text-color;
            padding-top: 8dip;
            margin-bottom: 0dip;
            margin-left: 16dip;
            margin-right: 16dip;
            border-style: none; 
            background-color: $colors.surface;
            padding-left: 8dip;
            padding-right: 8dip;
            gx-show-edit-text-line: false;
            gx-invite-message-color: #8592A6; //change to token when defined
            font-size: 16dip;
            font-family: $fonts.primary-regular;
        }
        .Image {
            gx-label-class: attribute__label;
        }
        .WWImage {
            width: 44dip;
            height: 44dip;
            border-radius: 5dip;
        }
        .ViewImage {
            gx-label-class: ww__attribute__label--readonly;
            color: #3D4854; //change to token when defined
            background-color: $colors.surface;
            padding: 8dip;
            margin-left: 16dip;
            margin-right: 16dip;
        }
        .image--disabled {
            gx-label-class: ww__attribute__label--readonly;
            margin-top: 8dip;
            margin-left: 8dip;
            margin-right: 8dip;
            margin-bottom: 16dip;
            background-color: $colors.surface;
        }
    #endregion

    #region Label
        .attribute-login-label {
            font-family: $fonts.primary-semibold;
            font-size: 12dip;
            letter-spacing: 0.5dip;
            color: #c3c4c8;
        }
        .attribute__label--disabled {
            @include attribute__label;
            color: $colors.gray03;
        }
        .attribute__label {
            font-size: 12dip;
            font-family: $fonts.primary-regular;
            letter-spacing: 0.4dip;
            color: $colors.surface-negative;
        }
        .switch__label {
            font-size: 16dip;
            font-family: $fonts.primary-regular;
            color: $colors.text-color;
        }
        .attribute-label-bold {
            @include attribute-login-label;
            color: #000000;
        }
        //workwith
        .ww__attribute__label--readonly {
            font-size: 12dip;
            font-family: $fonts.primary-regular;
            letter-spacing: 0.4dip;
            color: $colors.on-background;
        }
    #endregion

    #region Button
        .button {
            border-radius: 4dip;
            font-size: 16dip;
        }
        .button-primary {
            @include button;
            gx-elevation: 0;
            color: $colors.surface;
        }
        .button-secondary {
            @include button;
            gx-elevation: 0;
        }
        .button-tertiary {
            @include button;
            gx-elevation: 0;
        }
        .button-rounded {
            border-radius: 28dip;
            gx-elevation: 0;
        }
        .button-primary-destructive {
            @include button-primary;
            gx-elevation: 0;
        }
        //disabled
        .button-primary--disabled {
            @include button;
            background-color: $colors.gray03;
            color: $colors.on-disabled;
        }
        .button-secondary--disabled {
            @include button;
            color: $colors.gray03;
        }
        .button-tertiary--disabled {
            @include button;
            border-style: solid;
            border-width: 1dip;
            border-color: $colors.border-gray-03;
            color: $colors.gray03;
        }
        .button-rounded--disabled {
            @include button-rounded;
            background-color: $colors.gray03;
            color: $colors.on-disabled;
        }
    #endregion

    #region Badges
        .badge {
            gx-label-class: attribute__label;
            max-height: 32dip;
            margin-left: 16dip;
            margin-right: 16dip;
        }
        .badge-success {
            @include badge;
        }
        .badge-warning {
            @include badge;
        }
        .badge-danger {
            @include badge;
        }
        .badge-info {
            @include badge;
        }
    #endregion

    #region Textblock
        .TextBlock {
            font-family: $fonts.primary-regular;
            color: $colors.surface-negative;
            padding-left: 8dip;
        }
    #endregion

    #region Grid
        .Grid {
            gx-row-horizontal-line-separator: true;
            gx-horizontal-line-class: WWLineSeparator;
            background-color: $colors.surface;
        }
    #endregion

    #region Table
        .MainTable {
            padding: 0dip 0dip 16dip 0dip;
            background-color: $colors.surface;
            gx-row-horizontal-line-separator: false;
        }
        .TableDetail {
            background-color: $colors.surface;
            padding: 16dip 0dip 16dip 0dip;
            height: 100%;
            gx-row-horizontal-line-separator: false;
        }
        .TableSection {
            margin-top: 16dip;
            margin-bottom: 16dip;
            gx-row-horizontal-line-separator: true;
            gx-horizontal-line-class: WWLineSeparator;
        }
        .TableSectioninsert {
            margin-top: 16dip;
            margin-bottom: 16dip;
            gx-row-horizontal-line-separator: false;
        }
        .GridContainer {
            background-color: $colors.surface;
            gx-row-horizontal-line-separator: false;
        }
    #endregion

    #region Separator
        .WWLineSeparator {
            background-color: $colors.gray01;
            height: 1dip;
        }
    #endregion

    #region Tab
        .Tab {

        }
        .TabPageUnselected {
            font-family: $fonts.primary-regular;
            color: $colors.surface-negative;
        }
        .TabPageSelected {
            font-family: $fonts.primary-semibold;
            color: $colors.surface-negative;
        }
    #endregion

    #region Group
        .Group {          
            color: $colors.on-background;
            gx-caption-class: group__caption;
            gx-group-separator-class: group__separator;
        }
        .group__caption {
            color: $colors.on-background; 
            font-family: $fonts.primary-bold;
            letter-spacing: 0.4dip;
            font-size: 16dip;
        }
        .group__separator {
            margin-bottom: 20dip;
            margin-left: 20dip;
            background-color: transparent;
        }
    #endregion

    #region User Controls
        .Switch {
            padding-left: 16dip;
            padding-right: 8dip;
            gx-label-class: attribute__label;
            gx-switch-on-background-color: $colors.primary;
            gx-switch-on-text-color: $colors.primary-active;
            gx-switch-off-background-color: $colors.gray02;
            gx-switch-off-text-color: $colors.surface;
        }
        .switch--disabled {
            @include Switch;
            gx-switch-on-background-color: $colors.gray02;
            gx-switch-on-text-color: $colors.gray01;
            gx-switch-off-background-color: $colors.gray02;
            gx-switch-off-text-color: $colors.gray01;
        }
        .Slider {
            padding-left: 8dip;
            padding-right: 8dip;
            gx-label-class: attribute__label;
            gx-thumb-color: $colors.primary;
            gx-selected-bar-color: $colors.primary;
            gx-unselected-bar-color: $colors.gray01;
        }
        .slider--disabled {
            @include Slider;
            gx-thumb-color: $colors.gray03;
            gx-selected-bar-color: $colors.gray02;
            gx-unselected-bar-color: $colors.gray01;
        }
    #endregion
}

styles UnanimoAngular
{ 
    @import GeneXusUnanimo.Unanimo;
    @import GeneXusUnanimo.UnanimoControls;

    #region Application
        .Application {
            background-color: $colors.surface;
        }
        .ApplicationBars {
            background-color: $colors.header-bg;
            font-family: $fonts.primary-bold;
            color: $colors.on-secondary;
            border-bottom: solid 2px $colors.header-separator-bg;
        }
    #endregion

    #region Attribute
        .Attribute, .AttributeSearch {
            max-width: fit-content;
        }
        .Attribute.gx-disabled-custom {
            @include Attribute;
            color: $colors.gray03;
            background-color: $colors.gray01;
            border-color: $colors.border-gray-03;
        }
        .Attribute[type="date"], .Attribute[type="datetime-local"] {
            width: fit-content;
        }
        select.Attribute{
            max-width: fit-content;
        }
        .Attribute.gx-edit--multiline {
            min-width: 240px;
            min-height: 60px;
        }
        //checkbox
        .attribute-checkbox {
            --option-checked-color: $colors.primary;
            --option-border-color: $colors.gray04;
            --option-highlight-color: $colors.primary-active;
            gx-label-class: attribute-label;
        }
        gx-checkbox.Attribute {
            @include attribute-checkbox;
        }
        .attribute-checkbox--disabled {
            @include attribute-checkbox;
            --option-checked-color: $colors.primary-disabled;
            --option-border-color: $colors.border-primary-disabled;
            --option-highlight-color: unset;
        }
        //radio button
        gx-radio-option {
            --option-checked-color: $colors.primary;
            --option-border-color: $colors.gray04;
            --option-highlight-color: $colors.primary-active;
        }
        .attribute-radiobutton {
            gx-label-class: attribute-label;
        }
        .attribute-radiobutton--disabled {
            @include attribute-radiobutton;
            --option-checked-color: $colors.primary-disabled;
            --option-border-color: $colors.border-primary-disabled;
            --option-highlight-color: unset;
        }
        gx-radio-option .label-of-the-option {
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.s;
        }
    #endregion

    #region Badges
        //tag attributes ("badges")
        .badge {
            max-height: 18px;
            max-width: fit-content;
        }
        .badge-success, .badge-info, .badge-warning, .badge-danger, .badge-disabled {
            @include badge;
        }
    #endregion

    #region Button
        .Button {
            max-width: fit-content;
        }
        .Button::part(main-img) {
            padding-inline-start: $spacing.inline-l;
        }
        //image only
        .Button.gx-empty-caption {
            min-width: 28px;
            padding: 0px;
        }
        .Button.gx-empty-caption::part(main-img) {
            padding: 0px;
        }
        //button img
        .button-primary::part(main-img) {
            filter: brightness(0) saturate(100%) invert(100%) sepia(0%) saturate(7495%) hue-rotate(105deg) brightness(104%) contrast(100%);
        }
        .button-secondary::part(main-img) {
            filter: brightness(0) saturate(100%) invert(39%) sepia(90%) saturate(693%) hue-rotate(207deg) brightness(96%) contrast(97%);
        }
        .button-tertiary::part(main-img) {
            filter: brightness(0) saturate(100%) invert(39%) sepia(90%) saturate(693%) hue-rotate(207deg) brightness(96%) contrast(97%);
        }
        .button-rounded::part(main-img) {
            filter: brightness(0) saturate(100%) invert(100%) sepia(0%) saturate(7495%) hue-rotate(105deg) brightness(104%) contrast(100%);
        }
        //disabled state button img
        .button-primary--disabled::part(main-img) {
            filter: brightness(0) saturate(100%) invert(94%) sepia(11%) saturate(66%) hue-rotate(191deg) brightness(83%) contrast(90%);
        }
         .button-secondary--disabled::part(main-img) {
            filter: brightness(0) saturate(100%) invert(58%) sepia(10%) saturate(102%) hue-rotate(191deg) brightness(100%) contrast(84%);
        }
        .button-tertiary--disabled::part(main-img) {
            filter: brightness(0) saturate(100%) invert(58%) sepia(10%) saturate(102%) hue-rotate(191deg) brightness(100%) contrast(84%);
        }
        .button-rounded--disabled::part(main-img) {
            filter: brightness(0) saturate(100%) invert(94%) sepia(11%) saturate(66%) hue-rotate(191deg) brightness(83%) contrast(90%);
        }
    #endregion

    #region Group
        .gx-group-caption {
            display: block;
            color: $colors.on-background;
            font-family: $fonts.primary-bold;
            font-size: $fontSizes.m;
            letter-spacing: $spacing.letter-spacing-s;
            width: 100%;
            height: 30px;
            padding: 0;
            margin-bottom: $spacing.stack-l;
            border: 0;
            border-bottom: 1px solid $colors.gray01;
        }
    #endregion

    #region Grid
        .Grid {
            gx-grid-header-row-class: GridTitle;
            gx-grid-column-class: grid-column;
            gx-grid-row-class: grid-row;
            gx-grid-selected-row-class: gx-row-selected;
            gx-grid-hover-row-class: grid-row-highlight;
        }
        .GridTitle {
            font-family: $fonts.primary-bold;
            font-size: $fontSizes.s;
            color: $colors.on-background;
            cursor: pointer;
            border-bottom: $borders.extra-small solid $colors.gray01;
            padding-block: 7px;
            padding-inline: $spacing.inset-s;
        }
    #endregion

    #region Image
        .Image, .ViewImage {
            gx-label-class: attribute-label;
        }
    #endregion

    #region Switch
        .Switch {
            --option-checked-color: $colors.primary-active;
            --option-border-color: $colors.gray04;
            --option-highlight-color: $colors.primary-active;
            gx-label-class: attribute-label;
        }
        gx-switch>.gx-switch-container>.gx-switch-slider::before {
            width: 24px;
            height: 24px;
        }
        gx-switch>.gx-switch-container>.gx-switch-slider {
            width: 48px;
            height: 12px;
            border-radius: 12px;
            background-color: $colors.gray03;
        }
        gx-switch>.gx-switch-container--checked>.gx-switch-slider {
            background-color: $colors.primary;
        }
        //value text
        gx-switch>.gx-switch-container:last-child {
            font-family: $fonts.primary-regular;
            font-size: $fontSizes.s;
        }
    #endregion

    #region Tab
        .Tab {
            margin-inline: $spacing.inline-xl;
            gx-selected-tab-page-class: tab-item--selected;
            gx-unselected-tab-page-class: tab-item;
        }
        .Tab::part(tab-content){
            background-color: $colors.form-container-bg;
        }
        .Tab .ApplicationBars {
            background-color: $colors.form-container-bg;
            border-bottom: none;
        }
        .tab-item {
            padding: 10px;
            border-block-end-width: 3px;
        }
        .tab-item--selected {
            padding: 10px;
        }
        .tab-item:hover, tab-item--selected:hover {
            //border-block-end-color: $colors.primary-active;
            //border-block-end-width: 3px;
            box-shadow: 0px 3px 0px 0px $colors.secondary;
        }
        .tab-item:focus, tab-item--selected:focus {
            border: solid 1px $colors.secondary-active;
        }
    #endregion

    #region Table
        .gx-sections-container {
            background-color: $colors.alt-surface;
        }
        .TableDetail {
            background-color: $colors.alt-surface;
        }
        .TableSectioninsert {
            margin: 32px;
            padding: 32px;
            background-color: $colors.form-container-bg;
            border-radius: $radius.xl;
            box-shadow: $shadows.xxs;
            gx-row-horizontal-line-separator: true;
        }
        .TableSectioninsert gx-form-field {
            border-bottom: solid 1px $colors.gray03;
        }
    #endregion

    #region Master Panel
        .HeaderContainer {
            margin: 0px;
        }
    #endregion

    #region WorkWith
        .TableSectioninsert gx-map {
            --gx-map-width: 200px;
            --gx-map-height: 80px;
        }
    #endregion
}
